INSERT INTO `chatbot_adaptive_logs` (`id`, `id_mahasiswa`, `nim`, `nama`, `id_kelas`, `kelas`, `id_level`, `level_soal`, `id_soal`, `jenis_soal`, `jumlah_langkah`, `waktu_mulai`, `waktu_selesai`, `id_label_skor`, `labeling`, `durasi_menit`, `total_akses_chatbot_adaptive`, `pesan_bimbingan`, `detail`, `created_at`, `updated_at`, `deleted_at`) VALUES
('019d7d7e-793f-71b0-b647-386f24f7a0bc', '019bd119-feea-72db-ae7f-6eab643a243d', '2241760023', 'Mochammad Dicky Hanun Prasetyo', '01984a60-f7eb-737d-a267-6afadbf35e7e', 'TI-1C', '019863c4-59f9-7319-9104-08267fc3c551', 'Queue', '01996b09-9329-7208-be28-2b82f0987b22', 'Menambah Antrian', 19, '2026-04-11 10:01:30', '2026-04-11 10:02:13', NULL, 'Gaming the System', 0, 59, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-12 00:02:13 WIB\", \"respons\": \"Halo! Mari kita pahami soal \\\"Menambah Antrian\\\" ini dengan lebih teliti.\\n\\n**Penjelasan Soal**\\nSoal ini meminta Anda membuat pseudocode untuk menambahkan pelanggan baru ke dalam antrian (**Queue**) dengan memastikan antrian tidak penuh terlebih dahulu.\\n\\n**Tipe Data**\\n*   **string[]**: Digunakan untuk representasi antrian yang menyimpan nama-nama pelanggan.\\n*   **string**: Representasi nama pelanggan baru yang akan ditambahkan.\\n*   **int**: Kemungkinan digunakan untuk ukuran antrian atau indeks.\\n*   **char[]**: Tidak secara langsung terlibat dalam konteks soal ini, kecuali jika nama pelanggan dipecah menjadi karakter.\\n*   **char**: Sama seperti `char[]`, tidak secara langsung terlibat.\\n\\n**Kondisi**\\n*   **IF-ELSE**: Akan digunakan untuk memeriksa apakah antrian sudah penuh sebelum operasi penambahan.\\n\\n**Queue**\\n*   Struktur data yang mengikuti prinsip FIFO (First-In, First-Out).\\n*   Operasi `enqueue()` digunakan untuk menambah elemen ke belakang antrian.\\n\\n**Algoritma**\\n1.  Menerima data pelanggan baru.\\n2.  Memeriksa kondisi apakah antrian sudah penuh.\\n3.  Jika tidak penuh, tambahkan pelanggan ke antrian.\\n\\n**Petunjuk Memahami Soal**\\n1.  Fokus pada syarat: \\\"periksa apakah sudah penuh *sebelum* menambah\\\". Ini krusial untuk struktur kondisi Anda.\\n2.  Bagaimana cara \\\"memeriksa apakah sudah penuh\\\" dalam konteks sebuah **Queue**? Pikirkan properti atau fungsi yang mungkin dimiliki Queue.\\n3.  Ingat operasi `enqueue()` hanya dilakukan jika kondisi antrian tidak penuh terpenuhi.\", \"created_at\": \"2026-04-11 17:02:13\"}], \"access_id\": \"019d7d7e-5e09-71e9-a369-adfbd7868976\", \"waktu_detik\": 43, \"durasi_detik\": 29, \"triggered_at\": \"2026-04-11 17:02:13\", \"jumlah_langkah\": 19, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-11 17:02:35\", \"popup_opened_at\": \"2026-04-11 17:02:06\", \"waktu_akses_detik\": 43}', '2026-04-11 10:02:13', '2026-04-11 10:02:35', NULL),
('019d7d90-6f3b-7392-9e85-9569870a13ec', '0178f025-d3eb-4e02-86c7-e1b4f083506a', '244107060064', 'SALLY SAVISTA ANINDYA', '01997051-0d1a-7091-8ec0-d181c7bbf04b', 'SIB-1D', '01995dec-678e-70cf-854a-b25e2c2d0d28', 'Tipe Data', '01995df6-35ed-7363-9d42-578622c3e4f2', 'Program Hitung Harga Motor', 20, '2026-04-11 10:21:07', '2026-04-11 10:21:50', NULL, 'Gaming the System', 0, 1, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-12 00:21:50 WIB\", \"respons\": \"**Penjelasan Soal**\\nAnda perlu menghitung total pembayaran motor setelah harga awal ditambah pajak penjualan.\\n\\n**Tipe Data**\\n- **double** atau **float**: Ideal untuk harga motor dan pajak karena melibatkan desimal dan presisi.\\n- **int**: Digunakan untuk bilangan bulat, jika ada variabel tanpa nilai desimal.\\n\\n**Algoritma**\\n- Definisikan nilai awal (harga, persentase pajak).\\n- Hitung jumlah pajak.\\n- Hitung total harga akhir.\\n\\n**Petunjuk Memahami Soal**\\n1. Tentukan semua nilai yang diketahui dari soal.\\n2. Pilih tipe data paling tepat untuk setiap nilai, pertimbangkan presisi **double** vs **float**.\\n3. Susun urutan langkah perhitungan: pajak dulu, lalu total.\\n4. Jangan terburu-buru, pastikan setiap variabel memiliki tipe data yang benar.\", \"created_at\": \"2026-04-11 17:21:50\"}], \"access_id\": \"019d7d90-5002-7257-af5c-232326a5ccf6\", \"waktu_detik\": 43, \"durasi_detik\": 17, \"triggered_at\": \"2026-04-11 17:21:50\", \"jumlah_langkah\": 20, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-11 17:21:59\", \"popup_opened_at\": \"2026-04-11 17:21:42\", \"waktu_akses_detik\": 43}', '2026-04-11 10:21:50', '2026-04-11 10:21:59', NULL),
('019d89c4-40d3-71a9-b862-b8dc9e3bde0d', '019bd119-feea-72db-ae7f-6eab643a243d', '2241760023', 'Mochammad Dicky Hanun Prasetyo', '01984a60-f7eb-737d-a267-6afadbf35e7e', 'TI-1C', '01995dec-678e-70cf-854a-b25e2c2d0d28', 'Tipe Data', '01995df6-35ed-7363-9d42-578622c3e4f2', 'Program Hitung Harga Motor', 20, '2026-04-13 19:13:12', '2026-04-13 19:13:53', NULL, 'Gaming the System', 0, 61, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-14 09:13:53 WIB\", \"respons\": \"Maaf, saya sedang tidak dapat merespons saat ini. Silakan coba lagi.\", \"created_at\": \"2026-04-14 02:13:53\"}], \"access_id\": \"019d89c4-24a2-70dd-af86-596db10134ee\", \"waktu_detik\": 41, \"durasi_detik\": 27, \"triggered_at\": \"2026-04-14 02:13:53\", \"jumlah_langkah\": 20, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-14 02:14:13\", \"popup_opened_at\": \"2026-04-14 02:13:46\", \"waktu_akses_detik\": 41}', '2026-04-13 19:13:53', '2026-04-13 19:14:13', NULL),
('019d89c7-33a5-72f5-960b-c31a51c753b6', '019bd119-feea-72db-ae7f-6eab643a243d', '2241760023', 'Mochammad Dicky Hanun Prasetyo', '01984a60-f7eb-737d-a267-6afadbf35e7e', 'TI-1C', '01995dec-678e-70cf-854a-b25e2c2d0d28', 'Tipe Data', '01995df6-35ed-7363-9d42-578622c3e4f2', 'Program Hitung Harga Motor', 20, '2026-04-13 19:16:25', '2026-04-13 19:17:06', NULL, 'Gaming the System', 0, 62, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-14 09:17:06 WIB\", \"respons\": \"**Penjelasan Soal**\\nSoal ini meminta Anda menghitung total uang yang harus dibayar Pak Hari untuk sepeda motor, termasuk pajak penjualan.\\n\\n**Tipe Data**\\n*   **int**: Digunakan untuk menyimpan bilangan bulat (contoh: 1, 25, 100).\\n*   **float**: Digunakan untuk menyimpan bilangan desimal dengan presisi tunggal.\\n*   **double**: Mirip dengan **float**, namun memiliki presisi ganda, lebih cocok untuk angka desimal yang besar atau perhitungan finansial.\\n\\n**Algoritma**\\n1.  Mulai dengan harga awal sepeda motor.\\n2.  Tentukan persentase pajak yang berlaku.\\n3.  Hitung jumlah pajak berdasarkan harga dan persentase.\\n4.  Tambahkan jumlah pajak ke harga awal untuk mendapatkan total yang harus dibayar.\\n\\n**Petunjuk Memahami Soal**\\n1.  Perhatikan nilai harga motor yang besar dan potensi hasil perhitungan pajak yang memiliki desimal.\\n2.  Pikirkan tipe data mana (**float** atau **double**) yang paling tepat untuk menyimpan nilai uang agar hasilnya akurat.\\n3.  Pastikan Anda menghitung pajak terlebih dahulu, lalu menambahkannya ke harga awal.\\n4.  Bagaimana cara mengkonversi persentase (10%) menjadi angka yang bisa dihitung?\", \"created_at\": \"2026-04-14 02:17:06\"}], \"access_id\": \"019d89c7-076f-7142-ba9c-f47f258288a9\", \"waktu_detik\": 41, \"durasi_detik\": 18, \"triggered_at\": \"2026-04-14 02:17:06\", \"jumlah_langkah\": 20, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-14 02:17:13\", \"popup_opened_at\": \"2026-04-14 02:16:55\", \"waktu_akses_detik\": 41}', '2026-04-13 19:17:06', '2026-04-13 19:17:14', NULL),
('019d8aa9-c3df-73a0-a72f-c62b13247129', '019bd119-feea-72db-ae7f-6eab643a243d', '2241760023', 'Mochammad Dicky Hanun Prasetyo', '01984a60-f7eb-737d-a267-6afadbf35e7e', 'TI-1C', '01995dec-678e-70cf-854a-b25e2c2d0d28', 'Tipe Data', '01995df6-35ed-7363-9d42-578622c3e4f2', 'Program Hitung Harga Motor', 23, '2026-04-13 23:23:52', '2026-04-13 23:24:34', NULL, 'Gaming the System', 1, 63, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-14 13:24:34 WIB\", \"respons\": \"**Penjelasan Soal**\\nSoal ini bertujuan untuk menghitung total uang yang harus dibayar Pak Hari setelah harga motor ditambah pajak penjualan.\\n\\n**Tipe Data**\\n*   **int**: Digunakan untuk bilangan bulat murni tanpa angka di belakang koma, seperti jumlah unit atau tahun.\\n*   **float**: Digunakan untuk bilangan desimal dengan presisi tunggal, cocok untuk nilai yang tidak membutuhkan ketelitian sangat tinggi.\\n*   **double**: Digunakan untuk bilangan desimal dengan presisi ganda, sangat disarankan untuk perhitungan moneter atau nilai yang membutuhkan akurasi tinggi.\\n\\n**Algoritma**\\n*   Inisialisasi harga motor dan persentase pajak.\\n*   Hitung jumlah pajak yang dikenakan dari harga motor.\\n*   Jumlahkan harga motor dengan pajak untuk mendapatkan total bayar.\\n\\n**Petunjuk Memahami Soal**\\n1.  Baca soal dengan teliti: Identifikasi semua angka dan persentase yang diberikan.\\n2.  Pahami perhitungan persentase: Bagaimana cara menghitung 10% dari suatu nilai?\\n3.  Pilih tipe data yang tepat: Pertimbangkan apakah nilai yang dihitung akan berupa bilangan bulat atau desimal, dan seberapa tinggi presisinya.\\n4.  Susun langkah perhitungan: Urutkan proses dari menentukan nilai awal, menghitung pajak, hingga mendapatkan total akhir.\", \"created_at\": \"2026-04-14 06:24:34\"}, {\"waktu\": \"2026-04-14 13:25:41 WIB\", \"source\": \"adaptive_conversation\", \"bot_name\": \"PseudoLearn Chatbot AI\", \"access_id\": \"019d8aa9-a2de-7246-8567-b2ccd08c5c8a\", \"created_at\": \"2026-04-14 06:25:41\", \"bot_response\": \"Maaf, saya sedang tidak dapat merespons saat ini. Silakan coba lagi.\", \"mahasiswa_name\": \"Mochammad Dicky Hanun Prasetyo\", \"mahasiswa_message\": \"apa itu tipe data?\"}, {\"waktu\": \"2026-04-14 13:26:05 WIB\", \"source\": \"adaptive_conversation\", \"bot_name\": \"PseudoLearn Chatbot AI\", \"access_id\": \"019d8aa9-a2de-7246-8567-b2ccd08c5c8a\", \"created_at\": \"2026-04-14 06:26:05\", \"bot_response\": \"Halo! Wah, ini pertanyaan yang bagus sekali tentang **tipe data** dalam pemrograman. Memahami perbedaan antara `float` dan `double` itu penting banget lho, terutama saat kamu berurusan dengan angka-angka yang memiliki koma atau nilai desimal.\\n\\n**Apa Itu `float` dan `double`?**\\n\\nBaik `float` maupun `double` adalah tipe data yang digunakan untuk menyimpan bilangan riil, yaitu angka yang bisa memiliki bagian desimal (contoh: 3.14, -0.5, 100.0). Keduanya termasuk dalam kategori \\\"floating-point numbers\\\". Perbedaan utamanya terletak pada seberapa \\\"akurat\\\" atau \\\"presisi\\\" angka tersebut bisa disimpan, dan juga berapa banyak memori yang mereka gunakan.\\n\\n**Perbedaan Utama: Presisi dan Ukuran Memori**\\n\\nPerbedaan paling mendasar antara `float` dan `double` adalah pada tingkat **presisi** yang bisa mereka tawarkan, yang juga berimbas pada **ukuran memori** yang dibutuhkan:\\n\\n*   **`float`**: Ini adalah singkatan dari \\\"single-precision floating-point\\\". Artinya, ia bisa menyimpan angka desimal dengan tingkat ketelitian yang lebih rendah. Umumnya, `float` menggunakan 32 bit (4 byte) memori dan dapat menyimpan sekitar 6-7 digit desimal yang signifikan.\\n*   **`double`**: Ini adalah singkatan dari \\\"double-precision floating-point\\\". Sesuai namanya, ia menawarkan tingkat ketelitian dua kali lipat dari `float`. `double` biasanya menggunakan 64 bit (8 byte) memori, sehingga bisa menyimpan sekitar 15-17 digit desimal yang signifikan.\\n\\n**Kapan Menggunakan Masing-masing?**\\n\\nJadi, kapan sebaiknya kamu memilih `float` dan kapan `double`?\\n\\n*   Gunakan **`float`** ketika:\\n    *   Kamu membutuhkan angka desimal tetapi tidak memerlukan presisi yang sangat tinggi (misalnya, untuk menampilkan suhu, harga barang yang tidak terlalu krusial presisinya, atau dalam aplikasi grafis di mana performa lebih diutamakan daripada presisi absolut).\\n    *   Kamu ingin menghemat memori, terutama jika kamu menyimpan banyak sekali angka desimal.\\n*   Gunakan **`double`** ketika:\\n    *   Kamu membutuhkan presisi yang sangat tinggi untuk perhitungan (misalnya, dalam perhitungan ilmiah, keuangan, rekayasa, atau fisika di mana kesalahan pembulatan kecil bisa berdampak besar).\\n    *   Kamu tidak terlalu khawatir tentang penggunaan memori tambahan.\\n    *   Ini adalah pilihan *default* untuk banyak operasi matematika dalam banyak bahasa pemrograman karena menawarkan keseimbangan yang baik antara presisi dan performa.\\n\\nPenting untuk diingat bahwa presisi ini tidak berarti angka bisa disimpan *tanpa batas* akurat, karena komputer memiliki keterbatasan representasi bilangan riil. Namun, `double` jauh lebih baik dalam meminimalkan kesalahan pembulatan dibandingkan `float`.\\n\\nSemoga penjelasan ini membantumu memahami perbedaannya ya! Jika ada pertanyaan lain, jangan sungkan bertanya.\", \"mahasiswa_name\": \"Mochammad Dicky Hanun Prasetyo\", \"mahasiswa_message\": \"perbedaan double dan float opo?\"}], \"access_id\": \"019d8aa9-a2de-7246-8567-b2ccd08c5c8a\", \"waktu_detik\": 42, \"durasi_detik\": 105, \"triggered_at\": \"2026-04-14 06:24:34\", \"jumlah_langkah\": 23, \"total_messages\": 3, \"popup_closed_at\": \"2026-04-14 06:26:11\", \"popup_opened_at\": \"2026-04-14 06:24:26\", \"waktu_akses_detik\": 42}', '2026-04-13 23:24:34', '2026-04-13 23:26:11', NULL),
('019d8af1-c765-7089-99ba-871e05be5c36', '625e276f-f4dd-449b-88c3-5faf8679447c', '244107060009', 'ACHMAD ALFI MAKSUM', '01997051-0d1a-7091-8ec0-d181c7bbf04b', 'SIB-1D', '01995dec-678e-70cf-854a-b25e2c2d0d28', 'Tipe Data', '01995df6-35ed-7363-9d42-578622c3e4f2', 'Program Hitung Harga Motor', 25, '2026-04-14 00:42:33', '2026-04-14 00:43:14', NULL, 'Gaming the System', 0, 2, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-14 14:43:14 WIB\", \"respons\": \"Maaf, saya sedang tidak dapat merespons saat ini. Silakan coba lagi.\", \"created_at\": \"2026-04-14 07:43:14\"}, {\"waktu\": \"2026-04-14 14:43:43 WIB\", \"source\": \"adaptive_conversation\", \"bot_name\": \"PseudoLearn Chatbot AI\", \"access_id\": \"019d8af1-c040-7041-888c-01cd2b6eac15\", \"created_at\": \"2026-04-14 07:43:43\", \"bot_response\": \"Halo! Saya PseudoLearn Chatbot, asisten belajarmu di PseudoLearn. Senang sekali kamu sudah mulai mengerjakan soal-soal latihan.\\n\\n**Tugas Saya sebagai Asisten Belajar**\\nSebagai asisten belajar, tujuan utama saya adalah membantu kamu memahami konsep pemrograman dan menemukan solusi sendiri. Oleh karena itu, saya tidak bisa langsung memberikan jawaban dari soal yang sedang kamu kerjakan. Ini karena proses menemukan jawaban itu sendiri adalah bagian penting dari pembelajaranmu. Ketika kamu berusaha, berpikir, dan akhirnya menemukan solusinya, pemahamanmu akan jauh lebih dalam dan melekat.\\n\\n**Bagaimana Saya Bisa Membantumu?**\\nMeski tidak bisa memberikan jawaban langsung, saya bisa membantumu dengan berbagai cara, terutama karena kita sedang berada di level **Tipe Data**:\\n*   **Menjelaskan Konsep:** Apakah ada konsep tentang **tipe data** yang belum kamu pahami sepenuhnya? Misalnya, apa itu **integer**, **float**, **string**, atau **boolean**? Kapan kita harus menggunakan tipe data tertentu?\\n*   **Memberikan Hints:** Jika kamu kesulitan memulai atau terjebak di tengah jalan, ceritakan bagian mana yang membuatmu bingung. Saya bisa memberikan petunjuk atau arahan yang akan membimbingmu tanpa mengungkapkan jawabannya.\\n*   **Mengajukan Pertanyaan Pemandu:** Saya bisa mengajukan pertanyaan-pertanyaan yang akan memicu pemikiranmu dan membantumu melihat masalah dari sudut pandang yang berbeda.\\n\\nJadi, daripada menanyakan jawabannya, coba ceritakan apa yang sudah kamu coba, di mana kamu merasa kesulitan, atau konsep apa yang masih membingungkanmu dari soal tersebut. Mari kita pecahkan bersama-sama!\", \"mahasiswa_name\": \"ACHMAD ALFI MAKSUM\", \"mahasiswa_message\": \"bagaimana jawaban soal tersebut?\"}], \"access_id\": \"019d8af1-c040-7041-888c-01cd2b6eac15\", \"waktu_detik\": 41, \"durasi_detik\": 48, \"triggered_at\": \"2026-04-14 07:43:14\", \"jumlah_langkah\": 25, \"total_messages\": 2, \"popup_closed_at\": \"2026-04-14 07:44:00\", \"popup_opened_at\": \"2026-04-14 07:43:12\", \"waktu_akses_detik\": 41}', '2026-04-14 00:43:14', '2026-04-14 00:44:00', NULL),
('019d8b11-c89a-728d-bcc0-c711b16c6ef0', '8195fe6c-aa10-4bc5-bcc3-22c192750146', '244107060043', 'ADELIA RIZKI EKA PUTRI', '01997051-0d1a-7091-8ec0-d181c7bbf04b', 'SIB-1D', '019863c4-59f9-7319-9104-08267fc3c551', 'Queue', '01996b09-9329-7208-be28-2b82f0987b22', 'Menambah Antrian', 25, '2026-04-14 01:17:16', '2026-04-14 01:18:11', NULL, 'Struggling', 0, 2, '[ADAPTIVE - Struggling] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Struggling] Bimbingan materi otomatis\", \"waktu\": \"2026-04-14 15:18:11 WIB\", \"respons\": \"Maaf, saya sedang tidak dapat merespons saat ini. Silakan coba lagi.\", \"created_at\": \"2026-04-14 08:18:11\"}], \"access_id\": \"019d8b11-c369-73d2-b9ba-66b22fca2090\", \"waktu_detik\": 55, \"durasi_detik\": 18, \"triggered_at\": \"2026-04-14 08:18:11\", \"jumlah_langkah\": 25, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-14 08:18:28\", \"popup_opened_at\": \"2026-04-14 08:18:10\", \"waktu_akses_detik\": 55}', '2026-04-14 01:18:11', '2026-04-14 01:18:28', NULL),
('019d8f47-4dc5-720b-a72b-497bb1fdd116', '5effff16-9773-4149-9a4a-3ef5e3cf6156', '244107020195', 'ARYA RAMADHAN', '019873da-b95c-7218-80ca-086512e0c5a1', 'TI-1F', '01995dec-678e-70cf-854a-b25e2c2d0d28', 'Tipe Data', '01995df6-35ed-7363-9d42-578622c3e4f2', 'Program Hitung Harga Motor', 20, '2026-04-14 20:54:37', '2026-04-14 20:55:08', NULL, 'Gaming the System', 1, 1, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-15 10:55:08 WIB\", \"respons\": \"Maaf, saya sedang tidak dapat merespons saat ini. Silakan coba lagi.\", \"created_at\": \"2026-04-15 03:55:08\"}, {\"waktu\": \"2026-04-15 10:55:42 WIB\", \"source\": \"adaptive_conversation\", \"bot_name\": \"PseudoLearn Chatbot AI\", \"access_id\": \"019d8f47-3d34-7359-992b-96e3626fb141\", \"created_at\": \"2026-04-15 03:55:42\", \"bot_response\": \"Maaf, saya sedang tidak dapat merespons saat ini. Silakan coba lagi.\", \"mahasiswa_name\": \"ARYA RAMADHAN\", \"mahasiswa_message\": \"bagaimana maksud dari jawaban kamu?\"}, {\"waktu\": \"2026-04-15 10:55:59 WIB\", \"source\": \"adaptive_conversation\", \"bot_name\": \"PseudoLearn Chatbot AI\", \"access_id\": \"019d8f47-3d34-7359-992b-96e3626fb141\", \"created_at\": \"2026-04-15 03:55:59\", \"bot_response\": \"Tentu, dengan senang hati! Mari kita bahas lebih lanjut mengenai tipe data **float**. Ini adalah konsep yang sangat penting dalam pemrograman, terutama saat kita berurusan dengan angka-angka yang lebih kompleks.\\n\\n**Apa Itu Tipe Data Float?**\\n\\n**Float** (sering juga disebut *floating-point number*) adalah salah satu tipe data dasar yang digunakan untuk menyimpan angka-angka yang memiliki bagian desimal atau pecahan. Bayangkan angka-angka seperti 3.14, -0.5, atau 99.99. Semua angka ini membutuhkan tipe data **float** karena mereka tidak bulat sempurna. Berbeda dengan tipe data **integer** (bilangan bulat) yang hanya bisa menyimpan angka tanpa koma (misalnya 1, 50, -100), **float** memungkinkan kita untuk merepresentasikan nilai yang lebih presisi.\\n\\n**Kapan Kita Menggunakan Float?**\\n\\nAnda akan sering menggunakan **float** dalam berbagai skenario, seperti:\\n*   **Perhitungan keuangan:** Misalnya, harga barang (Rp 15.500,75), suku bunga, atau diskon.\\n*   **Pengukuran:** Seperti tinggi badan (1.75 meter), suhu (25.5 derajat Celsius), atau jarak.\\n*   **Ilmu pengetahuan dan teknik:** Banyak perhitungan fisika, matematika, atau statistik melibatkan angka desimal.\\n\\nPenting untuk diingat bahwa meskipun **float** memberikan presisi, ada batasan tertentu. Komputer merepresentasikan angka **float** dengan cara yang sedikit berbeda dari angka bulat, dan terkadang ini bisa menyebabkan sedikit ketidakakuratan pada digit desimal terakhir dalam perhitungan yang sangat kompleks. Namun, untuk sebagian besar kasus penggunaan sehari-hari, **float** sudah lebih dari cukup akurat.\\n\\nSemoga penjelasan ini membantu Anda memahami apa itu tipe data **float**! Jika ada pertanyaan lain, jangan ragu untuk bertanya, ya.\", \"mahasiswa_name\": \"ARYA RAMADHAN\", \"mahasiswa_message\": \"apakah bisa dijelaskan mengenai float?\"}], \"access_id\": \"019d8f47-3d34-7359-992b-96e3626fb141\", \"waktu_detik\": 31, \"durasi_detik\": 60, \"triggered_at\": \"2026-04-15 03:55:08\", \"jumlah_langkah\": 20, \"total_messages\": 3, \"popup_closed_at\": \"2026-04-15 03:56:03\", \"popup_opened_at\": \"2026-04-15 03:55:03\", \"waktu_akses_detik\": 31}', '2026-04-14 20:55:08', '2026-04-14 20:56:03', NULL),
('019d8fc6-345a-71e1-9d17-ab67c70d44be', '6972665d-2dda-4bf9-9b2c-8e74875d51e9', '244107060115', 'AKHMAD HASAN KURNIAWAN', '01997051-0d1a-7091-8ec0-d181c7bbf04b', 'SIB-1D', '01995dec-678e-70cf-854a-b25e2c2d0d28', 'Tipe Data', '01995df6-35ed-7363-9d42-578622c3e4f2', 'Program Hitung Harga Motor', 15, '2026-04-14 23:13:09', '2026-04-14 23:13:44', NULL, 'Gaming the System', 0, 2, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-15 13:13:44 WIB\", \"respons\": \"Halo! Mari kita pahami soal ini lebih teliti agar kamu tidak perlu menebak-nebak.\\n\\n**Penjelasan Soal**\\nSoal ini meminta kamu menghitung total uang yang harus dibayar Pak Hari untuk sepeda motor setelah ditambahkan pajak penjualan.\\n\\n**Tipe Data**\\n*   **double**: Digunakan untuk menyimpan angka desimal dengan presisi tinggi. Sangat cocok untuk nilai uang atau hasil perhitungan persentase.\\n*   **int**: Digunakan untuk menyimpan bilangan bulat (tanpa desimal). Kurang tepat jika nilai yang disimpan bisa memiliki koma, seperti harga atau hasil pajak.\\n*   **float**: Mirip dengan **double**, namun memiliki presisi desimal yang lebih rendah. Pertimbangkan apakah presisi ini cukup untuk perhitungan uang.\\n\\n**Algoritma**\\n*   Definisikan harga awal sepeda motor.\\n*   Hitung besaran pajak penjualan dari harga awal.\\n*   Jumlahkan harga awal dengan besaran pajak untuk mendapatkan total pembayaran.\\n\\n**Petunjuk Memahami Soal**\\n1.  Identifikasi semua nilai numerik yang ada dalam soal (harga, persentase).\\n2.  Pikirkan, apakah nilai-nilai ini selalu bilangan bulat, atau bisa memiliki angka di belakang koma?\\n3.  Perhatikan cara menghitung persentase dari suatu nilai.\\n4.  Susun langkah-langkah perhitungan secara berurutan dan logis.\", \"created_at\": \"2026-04-15 06:13:44\"}, {\"waktu\": \"2026-04-15 13:14:09 WIB\", \"source\": \"adaptive_conversation\", \"bot_name\": \"PseudoLearn Chatbot AI\", \"access_id\": \"019d8fc6-0eff-72f8-b8c4-05e670e725e4\", \"created_at\": \"2026-04-15 06:14:09\", \"bot_response\": \"Halo! Pertanyaan yang bagus sekali, memahami perbedaan antara berbagai **tipe data** adalah langkah awal yang sangat penting dalam belajar pemrograman. Kamu sedang menanyakan perbedaan antara `double` dan `int`, mari kita bahas!\\n\\n**Mengenal Tipe Data `int`**\\nTipe data `int` (singkatan dari *integer*) digunakan untuk menyimpan bilangan bulat, yaitu angka tanpa bagian desimal. Contohnya seperti 1, 100, -5, atau 0. `int` sangat cocok digunakan ketika kamu perlu menghitung jumlah sesuatu yang tidak mungkin memiliki nilai pecahan, seperti jumlah siswa, jumlah barang, atau tahun. Karena hanya menyimpan bilangan bulat, `int` umumnya menggunakan memori yang relatif lebih kecil dibandingkan tipe data untuk bilangan desimal dan operasi matematika dengannya cenderung lebih cepat.\\n\\n**Mengenal Tipe Data `double`**\\nDi sisi lain, tipe data `double` digunakan untuk menyimpan bilangan riil atau bilangan pecahan, yaitu angka yang memiliki bagian desimal. Contohnya seperti 3.14, 0.5, -10.25, atau 123.456789. `double` seringkali digunakan untuk perhitungan yang membutuhkan presisi tinggi, seperti perhitungan keuangan, pengukuran ilmiah, atau representasi nilai-nilai seperti pi (π). Tipe data ini dapat menyimpan angka yang sangat besar atau sangat kecil dan dengan banyak angka di belakang koma, namun konsekuensinya adalah penggunaan memori yang lebih besar dan operasi yang sedikit lebih lambat dibanding `int`.\\n\\n**Perbedaan Utama dan Kapan Menggunakannya**\\nPerbedaan paling mendasar adalah:\\n*   `int` untuk bilangan **bulat** (tidak ada desimal).\\n*   `double` untuk bilangan **pecahan** (ada desimal), seringkali dengan presisi tinggi.\\n\\nJadi, ketika kamu ingin menyimpan harga barang yang bisa jadi Rp 15.500,50, tipe data apa yang lebih cocok? Atau jika kamu hanya ingin menyimpan jumlah pelanggan yang pasti bulat, tipe data apa yang akan kamu pilih? Memilih tipe data yang tepat sangat penting agar programmu berjalan efisien dan hasilnya akurat.\", \"mahasiswa_name\": \"AKHMAD HASAN KURNIAWAN\", \"mahasiswa_message\": \"apa perbedaan antara double dan int?\"}], \"access_id\": \"019d8fc6-0eff-72f8-b8c4-05e670e725e4\", \"waktu_detik\": 35, \"durasi_detik\": 59, \"triggered_at\": \"2026-04-15 06:13:44\", \"jumlah_langkah\": 15, \"total_messages\": 2, \"popup_closed_at\": \"2026-04-15 06:14:34\", \"popup_opened_at\": \"2026-04-15 06:13:35\", \"waktu_akses_detik\": 35}', '2026-04-14 23:13:44', '2026-04-14 23:14:34', NULL),
('019d8fdb-c7b9-73c9-91cf-93e5887b1fd1', '1030465c-58b1-4b81-966b-a1de85bbaead', '244107060110', 'RIFQI HILMI MUBAROK', '01997051-0d1a-7091-8ec0-d181c7bbf04b', 'SIB-1D', '019863c4-59f9-7319-9104-08267fc3c551', 'Queue', '01996b09-9329-7208-be28-2b82f0987b22', 'Menambah Antrian', 13, '2026-04-14 23:36:35', '2026-04-14 23:42:14', NULL, 'Gaming the System', 5, 1, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-15 13:37:18 WIB\", \"respons\": \"Halo! Mari kita bedah soal ini agar kamu lebih teliti dalam memahami konsep.\\n\\n**Penjelasan Soal**\\nTujuan soal ini adalah membuat pseudocode untuk menambahkan pelanggan baru ke dalam sebuah antrian (**Queue**), dengan memeriksa apakah antrian tersebut sudah penuh terlebih dahulu.\\n\\n**Tipe Data**\\n*   **string**: Digunakan untuk menyimpan nama pelanggan baru.\\n*   **int**: Mungkin digunakan untuk menyimpan ukuran maksimum antrian atau status keberhasilan/kegagalan operasi.\\n*   **string[]**: Jika antrian diimplementasikan sebagai array, ini bisa jadi tipe data internalnya, tapi untuk operasi `enqueue()` biasanya kita berinteraksi dengan **Queue** secara abstrak.\\n*   **char[] / char**: Tidak relevan secara langsung untuk operasi penambahan pelanggan ini.\\n\\n**Kondisi**\\n*   **IF-ELSE**: Digunakan untuk memeriksa apakah antrian sudah penuh (**isFull()**) sebelum mencoba menambahkan elemen.\\n\\n**Queue**\\n*   Struktur data yang mengikuti prinsip FIFO (First-In, First-Out).\\n*   Operasi utama yang terlibat adalah `enqueue()` (menambah elemen) dan `isFull()` (memeriksa kapasitas).\\n\\n**Algoritma**\\n*   Menerima data pelanggan baru.\\n*   Memeriksa status antrian (apakah penuh?).\\n*   Menambahkan pelanggan jika antrian tidak penuh.\\n*   Memberikan pesan sesuai hasil operasi.\\n\\n**Petunjuk Memahami Soal**\\n1.  **Fokus pada Kondisi**: Apa yang harus diperiksa *sebelum* menambahkan pelanggan? Bagaimana kondisi ini diekspresikan dalam pseudocode?\\n2.  **Operasi Queue**: Ingat kembali fungsi dasar `enqueue()` dan fungsi untuk memeriksa kapasitas antrian.\\n3.  **Aliran Logika**: Urutkan langkah-langkah secara *sekuensial* dari awal hingga akhir. Jangan loncat-loncat.\\n4.  **Pesan Output**: Apa yang harus ditampilkan jika antrian penuh dan jika berhasil ditambahkan?\", \"created_at\": \"2026-04-15 06:37:18\"}, {\"waktu\": \"2026-04-15 13:38:52 WIB\", \"source\": \"adaptive_conversation\", \"bot_name\": \"PseudoLearn Chatbot AI\", \"access_id\": \"019d8fdb-aa60-70b6-8a19-9bc1d16e4738\", \"created_at\": \"2026-04-15 06:38:52\", \"bot_response\": \"Halo! Pertanyaan yang bagus sekali, ini adalah konsep dasar yang penting untuk dipahami dalam pemrograman. Mari kita bedah perbedaannya agar kamu semakin paham.\\n\\n**Memahami Tipe Data Dasar: `string`**\\n\\nKetika kamu melihat `string` (atau terkadang disebut `String`), ini merujakan pada sebuah **tipe data** yang digunakan untuk menyimpan satu rangkaian karakter atau teks tunggal. Bayangkan seperti sebuah kata, sebuah kalimat, atau bahkan sebuah paragraf. Semua itu adalah `string`. Misalnya, nama seseorang, judul buku, atau pesan \\\"Halo dunia!\\\" semuanya bisa disimpan sebagai `string`.\\n\\n*   **Contoh:** Jika kamu ingin menyimpan nama \\\"Budi\\\", kamu akan menggunakan variabel bertipe `string`.\\n*   **Fungsi:** Menyimpan dan memanipulasi teks tunggal.\\n\\n**Memahami Koleksi Data: `string[]` (Array of String)**\\n\\nNah, `string[]` adalah sesuatu yang berbeda. Tanda `[]` setelah tipe data `string` menunjukkan bahwa ini adalah sebuah **array** dari `string`. Apa itu array? Array adalah sebuah struktur data yang bisa menyimpan **kumpulan** atau **daftar** dari beberapa item yang memiliki tipe data yang sama. Jadi, `string[]` berarti sebuah daftar atau kumpulan dari beberapa `string`.\\n\\n*   **Contoh:** Jika kamu ingin menyimpan daftar nama-nama peserta (\\\"Budi\\\", \\\"Ani\\\", \\\"Cici\\\"), kamu akan menggunakan variabel bertipe `string[]`. Setiap elemen dalam daftar itu sendiri adalah sebuah `string` yang terpisah.\\n*   **Fungsi:** Menyimpan dan mengelola banyak nilai `string` dalam satu variabel yang terstruktur. Kamu bisa mengakses setiap `string` di dalamnya menggunakan indeks (misalnya, `namaPeserta[0]` untuk \\\"Budi\\\").\\n\\nSingkatnya, `string` itu seperti sebuah buku tunggal, sedangkan `string[]` itu seperti sebuah rak buku yang berisi banyak buku. Keduanya sama-sama berurusan dengan \\\"buku\\\" (atau teks), tetapi satu adalah entitas tunggal dan yang lain adalah koleksi dari entitas tersebut. Semoga penjelasan ini membantu kamu membedakannya dengan lebih jelas, ya!\", \"mahasiswa_name\": \"RIFQI HILMI MUBAROK\", \"mahasiswa_message\": \"apa perbedaan string[] dan string?\"}], \"access_id\": \"019d8fdb-aa60-70b6-8a19-9bc1d16e4738\", \"waktu_detik\": 43, \"durasi_detik\": 303, \"triggered_at\": \"2026-04-15 06:37:18\", \"jumlah_langkah\": 13, \"total_messages\": 2, \"popup_closed_at\": \"2026-04-15 06:42:14\", \"popup_opened_at\": \"2026-04-15 06:37:11\", \"waktu_akses_detik\": 43}', '2026-04-14 23:37:18', '2026-04-14 23:42:14', NULL),
('019d901c-66c1-7124-acf8-22032f5bf8bd', '019ce768-9f9e-72c2-b856-8ce76d6804da', '2241760010', 'Solikhin', '01984a60-f7eb-737d-a267-6afadbf35e7e', 'TI-1C', '01995dec-678e-70cf-854a-b25e2c2d0d28', 'Tipe Data', '01995df6-35ed-7363-9d42-578622c3e4f2', 'Program Hitung Harga Motor', 22, '2026-04-15 00:46:41', '2026-04-15 00:58:04', NULL, 'Struggling', 10, 7, '[ADAPTIVE - Struggling] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Struggling] Bimbingan materi otomatis\", \"waktu\": \"2026-04-15 14:47:53 WIB\", \"respons\": \"**Penjelasan Soal**\\nSoal ini meminta Anda menghitung total uang yang harus dibayar Pak Hari setelah harga motor ditambah pajak penjualan.\\n\\n**Tipe Data**\\n*   **double**: Digunakan untuk menyimpan angka desimal (pecahan) dengan presisi tinggi, seperti harga motor yang besar atau hasil perhitungan pajak.\\n*   **int**: Digunakan untuk menyimpan angka bulat, contohnya jika Anda merepresentasikan persentase pajak sebagai bilangan bulat (misal 10, bukan 0.10).\\n*   **float**: Mirip **double**, untuk angka desimal, namun dengan presisi lebih rendah. Bisa juga digunakan untuk harga atau persentase.\\n\\n**Algoritma**\\nAlgoritma adalah serangkaian langkah logis dan terstruktur untuk menyelesaikan suatu masalah. Dalam soal ini, Anda perlu:\\n*   Mendefinisikan nilai yang diketahui.\\n*   Menghitung pajak.\\n*   Menghitung total harga.\\n\\n**Petunjuk Memahami Soal**\\n1.  Identifikasi nilai-nilai yang sudah diketahui dalam soal (harga motor, persentase pajak).\\n2.  Pikirkan, langkah pertama apa yang perlu Anda hitung? (Petunjuk: hitung berapa *nilai uang* dari pajaknya).\\n3.  Setelah mengetahui nilai pajaknya, langkah selanjutnya adalah menghitung total uang yang harus dibayar.\\n4.  Pilih tipe data yang tepat untuk setiap nilai (harga motor, persentase pajak, nilai pajak, total harga) agar hasilnya akurat.\", \"created_at\": \"2026-04-15 07:47:53\"}], \"access_id\": \"019d901c-450e-7014-ac44-9930b8fbdfda\", \"waktu_detik\": 683, \"durasi_detik\": 620, \"triggered_at\": \"2026-04-15 07:47:53\", \"jumlah_langkah\": 22, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-15 07:58:04\", \"popup_opened_at\": \"2026-04-15 07:47:44\", \"waktu_akses_detik\": 683, \"waktu_detik_saat_close\": 683}', '2026-04-15 00:47:53', '2026-04-15 00:58:04', NULL),
('019d9040-2d07-7143-ab95-ead8e62dae79', '0198517f-0d58-7074-8b6d-7bb6a5a4a30e', '2141720030', 'Evi Amalia Midfia', '01984a60-f7eb-737d-a267-6afadbf35e7e', 'TI-1C', '01995dec-678e-70cf-854a-b25e2c2d0d28', 'Tipe Data', '01995e24-1a61-73eb-b623-a0220a69532e', 'Perhitungan Volume', 24, '2026-04-15 01:26:07', '2026-04-15 01:27:50', NULL, 'Gaming the System', 1, 14, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-15 15:26:58 WIB\", \"respons\": \"**Penjelasan Soal**\\nSoal ini meminta Anda membuat algoritma pseudocode untuk menghitung volume box nasi, dengan dimensi yang proporsional 20:20:7.\\n\\n**Tipe Data**\\n*   **int**: Tipe data **int** digunakan untuk menyimpan bilangan bulat (tanpa desimal) yang memiliki batasan ukuran tertentu.\\n*   **long**: Tipe data **long** juga untuk bilangan bulat, namun dapat menyimpan nilai yang jauh lebih besar dari **int**, penting untuk menghindari *overflow* pada perhitungan besar.\\n\\n**Algoritma**\\nAlgoritma ini akan meliputi:\\n*   Mendeklarasikan variabel untuk panjang, lebar, dan tinggi box.\\n*   Menginisialisasi nilai dimensi tersebut.\\n*   Melakukan perhitungan volume menggunakan rumus.\\n*   Menampilkan hasil volume box nasi.\\n\\n**Petunjuk Memahami Soal**\\n1.  Baca teliti deskripsi soal, terutama angka dimensi yang diberikan.\\n2.  Pikirkan langkah-langkah algoritma secara berurutan dan logis.\\n3.  Ingat kembali rumus dasar untuk menghitung volume balok.\\n4.  Teliti perbedaan antara tipe data **int** dan **long** untuk memastikan hasil akhir volume dapat tertampung dengan benar.\", \"created_at\": \"2026-04-15 08:26:58\"}], \"access_id\": \"019d9040-0b97-7227-b04a-61e1855a0751\", \"waktu_detik\": 103, \"durasi_detik\": 61, \"triggered_at\": \"2026-04-15 08:26:58\", \"jumlah_langkah\": 24, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-15 08:27:50\", \"popup_opened_at\": \"2026-04-15 08:26:49\", \"waktu_akses_detik\": 103, \"waktu_detik_saat_close\": 103}', '2026-04-15 01:26:58', '2026-04-15 01:27:50', NULL),
('019d9069-1c56-7086-8cd6-ff672d4af4cb', 'a4178703-c659-45da-bae4-6de806558d0e', '244107020007', 'AFRIZAL RAFLI KUSUMA WARDANA', '019873da-b95c-7218-80ca-086512e0c5a1', 'TI-1F', '01995dec-678e-70cf-854a-b25e2c2d0d28', 'Tipe Data', '01995df6-35ed-7363-9d42-578622c3e4f2', 'Program Hitung Harga Motor', 19, '2026-04-15 02:11:06', '2026-04-15 02:12:13', NULL, 'Gaming the System', 0, 1, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-15 16:11:40 WIB\", \"respons\": \"Maaf, saya sedang tidak dapat merespons saat ini. Silakan coba lagi.\", \"created_at\": \"2026-04-15 09:11:40\"}], \"access_id\": \"019d9069-1121-70df-9866-33dae12be217\", \"waktu_detik\": 67, \"durasi_detik\": 36, \"triggered_at\": \"2026-04-15 09:11:40\", \"jumlah_langkah\": 19, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-15 09:12:13\", \"popup_opened_at\": \"2026-04-15 09:11:37\", \"waktu_akses_detik\": 67, \"waktu_detik_saat_close\": 67}', '2026-04-15 02:11:40', '2026-04-15 02:12:13', NULL),
('019d9198-84eb-7319-8b8b-9166b30e31c8', 'a1c5b086-be0f-499d-a08c-197a258b069c', '244107060007', 'ANJALI VIOLITA PRAMESTRI', '01997051-0d1a-7091-8ec0-d181c7bbf04b', 'SIB-1D', '019863c4-59f9-7319-9104-08267fc3c551', 'Queue', '01996b09-9329-7208-be28-2b82f0987b22', 'Menambah Antrian', 19, '2026-04-15 07:42:07', '2026-04-15 07:43:54', NULL, 'Gaming the System', 0, 1, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-15 21:43:05 WIB\", \"respons\": \"Halo! Mari kita bedah soal ini agar kamu lebih teliti dalam menyusun pseudocodenya.\\n\\n**Penjelasan Soal**\\nSoal ini meminta kamu membuat pseudocode untuk menambahkan pelanggan baru ke dalam antrian (**Queue**) menggunakan operasi `enqueue()`, sambil memastikan antrian tidak penuh terlebih dahulu.\\n\\n**Tipe Data**\\n*   **string**: Digunakan untuk menyimpan nama pelanggan.\\n*   **int**: Digunakan untuk merepresentasikan ukuran antrian atau jumlah elemen di dalamnya.\\n*   **string[]**: Array of string, bisa digunakan untuk merepresentasikan antrian itu sendiri jika diimplementasikan secara manual.\\n*   **char[]**: Array of char, tidak terlalu relevan langsung dengan soal ini.\\n*   **char**: Karakter tunggal, tidak terlalu relevan langsung dengan soal ini.\\n\\n**Queue**\\n*   **Queue**: Struktur data yang mengikuti prinsip FIFO (First-In, First-Out). Elemen ditambahkan di belakang (rear) dan dihapus dari depan (front).\\n*   **enqueue()**: Operasi untuk menambahkan elemen baru ke bagian belakang (rear) antrian.\\n\\n**Algoritma**\\n*   Menerima input nama pelanggan baru.\\n*   Memeriksa apakah antrian sudah mencapai kapasitas maksimumnya.\\n*   Jika belum penuh, tambahkan pelanggan ke antrian.\\n*   Jika sudah penuh, berikan pesan bahwa antrian tidak bisa menerima pelanggan baru.\\n\\n**Petunjuk Memahami Soal**\\n1.  Pikirkan langkah pertama yang harus dilakukan saat ada pelanggan baru.\\n2.  Bagaimana cara \\\"memeriksa apakah sudah penuh\\\" dalam pseudocode? Kondisi apa yang kamu butuhkan?\\n3.  Perhatikan urutan operasi: cek dulu atau langsung tambah?\\n4.  Pastikan kamu menggunakan operasi `enqueue()` yang spesifik untuk Queue.\", \"created_at\": \"2026-04-15 14:43:05\"}], \"access_id\": \"019d9198-710c-71b2-94ff-7898c7f63e8b\", \"waktu_detik\": 107, \"durasi_detik\": 55, \"triggered_at\": \"2026-04-15 14:43:05\", \"jumlah_langkah\": 19, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-15 14:43:54\", \"popup_opened_at\": \"2026-04-15 14:42:59\", \"waktu_akses_detik\": 107, \"waktu_detik_saat_close\": 107}', '2026-04-15 07:43:05', '2026-04-15 07:43:54', NULL),
('019d91a3-47ee-72d3-8ded-b5328dd0f49e', '019bd119-feea-72db-ae7f-6eab643a243d', '2241760023', 'Mochammad Dicky Hanun Prasetyo', '01984a60-f7eb-737d-a267-6afadbf35e7e', 'TI-1C', '01995dec-678e-70cf-854a-b25e2c2d0d28', 'Tipe Data', '01995df6-35ed-7363-9d42-578622c3e4f2', 'Program Hitung Harga Motor', 19, '2026-04-15 07:54:12', '2026-04-15 07:55:09', NULL, 'Gaming the System', 0, 66, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-15 21:54:50 WIB\", \"respons\": \"Maaf, saya sedang tidak dapat merespons saat ini. Silakan coba lagi.\", \"created_at\": \"2026-04-15 14:54:50\"}], \"access_id\": \"019d91a3-3b5b-71ec-b6d3-28c190fd4667\", \"waktu_detik\": 57, \"durasi_detik\": 23, \"triggered_at\": \"2026-04-15 14:54:50\", \"jumlah_langkah\": 19, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-15 14:55:09\", \"popup_opened_at\": \"2026-04-15 14:54:46\", \"waktu_akses_detik\": 57, \"waktu_detik_saat_close\": 57}', '2026-04-15 07:54:50', '2026-04-15 07:55:09', NULL),
('019d91bd-4550-72c3-9f03-2e7f51e33975', 'cd3b0e43-239f-463e-a7ba-2d156fd601d0', '244107020012', 'ARDHAN DIKRI ACHMAD FAHRUDIN', '019873da-b95c-7218-80ca-086512e0c5a1', 'TI-1F', '01995dec-678e-70cf-854a-b25e2c2d0d28', 'Tipe Data', '01995df6-35ed-7363-9d42-578622c3e4f2', 'Program Hitung Harga Motor', 21, '2026-04-15 08:22:36', '2026-04-15 08:23:40', NULL, 'Gaming the System', 0, 2, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-15 22:23:13 WIB\", \"respons\": \"Maaf, saya sedang tidak dapat merespons saat ini. Silakan coba lagi.\", \"created_at\": \"2026-04-15 15:23:13\"}, {\"waktu\": \"2026-04-15 22:23:33 WIB\", \"source\": \"adaptive_conversation\", \"bot_name\": \"PseudoLearn Chatbot AI\", \"access_id\": \"019d91bd-3791-70c8-afb3-86160fdffa93\", \"created_at\": \"2026-04-15 15:23:33\", \"bot_response\": \"Halo! Tentu saja, saya di sini untuk membantu kamu belajar dan memahami konsep-konsep pemrograman, struktur data, dan algoritma, khususnya yang berkaitan dengan pseudocode. Saya adalah asisten belajar AI dari PseudoLearn.\\n\\n**Bagaimana Saya Bisa Membantu Kamu?**\\nKamu bisa bertanya apa saja seputar materi pemrograman. Saat ini, kita sedang fokus pada topik **Tipe Data**. Jadi, jika ada konsep tipe data yang membingungkan, atau kamu butuh penjelasan lebih lanjut, jangan ragu untuk bertanya.\\n\\nSilakan sampaikan pertanyaan atau masalah yang sedang kamu hadapi, ya! Saya akan berusaha memberikan penjelasan, hints, atau pertanyaan pemandu agar kamu bisa menemukan solusinya sendiri.\", \"mahasiswa_name\": \"ARDHAN DIKRI ACHMAD FAHRUDIN\", \"mahasiswa_message\": \"apakah kamu bisa membantu saya?\"}], \"access_id\": \"019d91bd-3791-70c8-afb3-86160fdffa93\", \"waktu_detik\": 33, \"durasi_detik\": 31, \"triggered_at\": \"2026-04-15 15:23:13\", \"jumlah_langkah\": 21, \"total_messages\": 2, \"popup_closed_at\": \"2026-04-15 15:23:40\", \"popup_opened_at\": \"2026-04-15 15:23:09\", \"waktu_akses_detik\": 33, \"waktu_detik_saat_close\": 64}', '2026-04-15 08:23:13', '2026-04-15 08:23:40', NULL),
('019d944d-a517-707b-af91-af316dcfd888', 'e4c77a05-9e5d-4d53-90b8-026f5089d9bf', '244107060049', 'DIAN PARAMITHA', '01997051-0d1a-7091-8ec0-d181c7bbf04b', 'SIB-1D', '01995dec-678e-70cf-854a-b25e2c2d0d28', 'Tipe Data', '01995df6-35ed-7363-9d42-578622c3e4f2', 'Program Hitung Harga Motor', 19, '2026-04-15 20:15:35', '2026-04-15 20:20:59', NULL, 'Struggling', 1, 1, '[ADAPTIVE - Struggling] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Struggling] Bimbingan materi otomatis\", \"waktu\": \"2026-04-16 10:20:09 WIB\", \"respons\": \"**Penjelasan Soal**\\nAnda diminta menghitung total harga motor yang harus dibayar, setelah ditambahkan pajak penjualan.\\n\\n**Tipe Data**\\n*   **double**: Digunakan untuk menyimpan angka desimal yang besar, cocok untuk harga motor (25.000.000) dan total pembayaran.\\n*   **int**: Digunakan untuk menyimpan angka bulat, seperti nilai persentase pajak (10).\\n*   **float**: Mirip **double**, namun dengan presisi (ketelitian) yang lebih rendah.\\n\\n**Algoritma**\\n*   Tentukan variabel untuk harga motor dan persentase pajak.\\n*   Hitung jumlah nilai pajak dalam rupiah.\\n*   Jumlahkan harga motor dengan nilai pajak untuk mendapatkan total.\\n\\n**Petunjuk Memahami Soal**\\n1.  Identifikasi nilai awal yang diketahui: harga motor dan persentase pajak.\\n2.  Pikirkan bagaimana menghitung berapa rupiah nilai dari \\\"pajak penjualan sebesar 10%\\\".\\n3.  Setelah mengetahui jumlah pajak, bagaimana Anda mendapatkan total uang yang harus dibayar?\\n4.  Pilih tipe data yang tepat untuk setiap nilai agar perhitungan akurat.\", \"created_at\": \"2026-04-16 03:20:09\"}], \"access_id\": \"019d944d-7592-7070-bbdf-5a266725f12a\", \"waktu_detik\": 262, \"durasi_detik\": 62, \"triggered_at\": \"2026-04-16 03:20:09\", \"jumlah_langkah\": 19, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-16 03:20:59\", \"popup_opened_at\": \"2026-04-16 03:19:57\", \"waktu_akses_detik\": 262, \"waktu_detik_saat_close\": 324}', '2026-04-15 20:20:09', '2026-04-15 20:20:59', NULL),
('019d9455-9aa9-73e1-aab8-9688016b1a73', '0198519c-8c85-73f9-b40c-51a8c56f03d6', '2141720300', 'Fadlila Afida', '01984a60-f7eb-737d-a267-6afadbf35e7e', 'TI-1C', '01995dec-678e-70cf-854a-b25e2c2d0d28', 'Tipe Data', '01995df6-35ed-7363-9d42-578622c3e4f2', 'Program Hitung Harga Motor', 22, '2026-04-15 20:27:56', '2026-04-15 20:29:41', NULL, 'Gaming the System', 1, 1, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-16 10:28:51 WIB\", \"respons\": \"**Penjelasan Soal**\\nSoal ini menghitung total harga sepeda motor yang harus dibayar Pak Hari setelah ditambahkan pajak penjualan.\\n\\n**Tipe Data**\\n*   **Double**: Untuk angka desimal dengan presisi tinggi, ideal untuk nilai mata uang besar.\\n*   **Int**: Untuk bilangan bulat, cocok untuk persentase jika diolah tanpa desimal.\\n\", \"created_at\": \"2026-04-16 03:28:51\"}], \"access_id\": \"019d9455-6eb5-7324-a8ef-8ab9f4a3f4fa\", \"waktu_detik\": 43, \"durasi_detik\": 62, \"triggered_at\": \"2026-04-16 03:28:51\", \"jumlah_langkah\": 22, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-16 03:29:41\", \"popup_opened_at\": \"2026-04-16 03:28:39\", \"waktu_akses_detik\": 43, \"waktu_detik_saat_close\": 105}', '2026-04-15 20:28:51', '2026-04-15 20:29:41', NULL),
('019d9484-6a65-70ac-9c58-33254deb699f', '0199704c-6fed-72f0-9a99-8b9c614ca6d0', '2141720130', 'Fadlila Afida 2', '01984a60-f7eb-737d-a267-6afadbf35e7e', 'TI-1C', '019863c4-59f9-7319-9104-08267fc3c551', 'Queue', '01996b09-9329-7208-be28-2b82f0987b22', 'Menambah Antrian', 23, '2026-04-15 21:19:08', '2026-04-15 21:25:31', NULL, 'Gaming the System', 5, 1, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-16 11:19:59 WIB\", \"respons\": \"Halo! Mari kita bedah soal ini agar kamu bisa menyusun pseudocode dengan lebih teliti.\\n\\n**Penjelasan Soal**\\nTujuan soal ini adalah membuat pseudocode untuk menambahkan pelanggan baru ke dalam antrian (**Queue**) menggunakan operasi `enqueue()`, dengan memastikan antrian tidak penuh terlebih dahulu.\\n\\n**Tipe Data**\\n*   **string[]**: Digunakan untuk menyimpan daftar nama pelanggan, bisa sebagai representasi antrian itu sendiri.\\n*   **string**: Akan digunakan untuk menyimpan nama pelanggan tunggal yang baru akan ditambahkan.\\n*   **int**: Digunakan untuk menyimpan ukuran antrian, kapasitas maksimum, atau indikator posisi.\\n*   **char[]**: Array karakter, bisa digunakan untuk merepresentasikan nama pelanggan jika dipecah per huruf, namun kurang relevan langsung di sini.\\n*   **char**: Karakter tunggal, seperti inisial pelanggan, juga kurang relevan langsung di sini.\\n\\n**Kondisi**\\n*   **IF**: Kondisi `IF` akan sangat penting untuk memeriksa apakah antrian sudah penuh (`isFull()`) sebelum mencoba menambahkan pelanggan baru.\\n\\n**Queue**\\n*   **Queue**: Struktur data yang mengikuti prinsip FIFO (First-In, First-Out).\\n*   **enqueue()**: Operasi untuk menambahkan elemen baru ke bagian belakang antrian.\\n*   **isFull()**: Fungsi yang akan memeriksa apakah antrian telah mencapai kapasitas maksimumnya.\\n\\n**Algoritma**\\n1.  Menerima input nama pelanggan baru.\\n2.  Memeriksa kondisi apakah antrian sudah penuh.\\n3.  Jika tidak penuh, tambahkan pelanggan ke antrian.\\n\\n**Petunjuk Memahami Soal**\\n1.  **Baca Teliti Deskripsi**: Fokus pada kata kunci \\\"menambah antrian\\\", \\\"enqueue()\\\", dan \\\"memeriksa apakah sudah penuh\\\".\\n2.  **Pahami Operasi Queue**: Ingat cara kerja `enqueue()` dan mengapa `isFull()` penting sebelum `enqueue()`.\\n3.  **Urutan Logika**: Pikirkan langkah-langkah secara berurutan: apakah kita cek penuh dulu, atau langsung tambahkan? Apa yang terjadi jika penuh?\\n4.  **Tipe Data untuk Pelanggan**: Pastikan kamu menggunakan tipe data yang tepat untuk nama pelanggan.\", \"created_at\": \"2026-04-16 04:19:59\"}], \"access_id\": \"019d9484-53ba-73f2-b594-7dece419270f\", \"waktu_detik\": 45, \"durasi_detik\": 338, \"triggered_at\": \"2026-04-16 04:19:59\", \"jumlah_langkah\": 23, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-16 04:25:31\", \"popup_opened_at\": \"2026-04-16 04:19:53\", \"waktu_akses_detik\": 45, \"waktu_detik_saat_close\": 383}', '2026-04-15 21:19:59', '2026-04-15 21:25:31', NULL);
INSERT INTO `chatbot_adaptive_logs` (`id`, `id_mahasiswa`, `nim`, `nama`, `id_kelas`, `kelas`, `id_level`, `level_soal`, `id_soal`, `jenis_soal`, `jumlah_langkah`, `waktu_mulai`, `waktu_selesai`, `id_label_skor`, `labeling`, `durasi_menit`, `total_akses_chatbot_adaptive`, `pesan_bimbingan`, `detail`, `created_at`, `updated_at`, `deleted_at`) VALUES
('019d94d3-31d4-73b2-93af-cbb76197ae92', 'bc346e33-a6fa-4957-b881-40c10795fff6', '244107020122', 'FARRELINO ATHAILLAH RIBERA', '019873da-b95c-7218-80ca-086512e0c5a1', 'TI-1F', '019863c4-59f9-7319-9104-08267fc3c551', 'Queue', '01996b09-9329-7208-be28-2b82f0987b22', 'Menambah Antrian', 24, '2026-04-15 22:45:01', '2026-04-15 22:46:09', NULL, 'Gaming the System', 0, 1, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-16 12:46:02 WIB\", \"respons\": \"Halo! Mari kita pahami soal ini lebih teliti.\\n\\n**Penjelasan Soal**\\nAnda diminta membuat pseudocode untuk menambahkan pelanggan baru ke dalam sebuah antrian (`queue`), dengan syarat harus memeriksa apakah antrian sudah penuh terlebih dahulu.\\n\\n**Tipe Data**\\n*   **string[]**: Array untuk merepresentasikan antrian pelanggan secara keseluruhan.\\n*   **string**: Digunakan untuk menyimpan nama pelanggan baru yang akan ditambahkan.\\n*   **int**: Digunakan untuk merepresentasikan ukuran antrian atau jumlah elemen saat ini.\\n*   **char[]** dan **char**: Meskipun disebutkan, tidak secara langsung terlibat dalam operasi `enqueue` pada soal ini.\\n\\n**Kondisi**\\n*   **Jika antrian penuh**: Kondisi ini harus diperiksa sebelum penambahan. Jika benar, penambahan dibatalkan.\\n*   **Jika antrian tidak penuh**: Kondisi ini memungkinkan penambahan pelanggan.\\n\\n**Queue**\\n*   Struktur data yang mengikuti prinsip FIFO (First-In, First-Out). Operasi `enqueue()` menambahkan elemen ke belakang antrian.\\n\\n**Algoritma**\\n*   Melibatkan proses input data pelanggan.\\n*   Pengecekan kondisi `penuh` pada antrian.\\n*   Eksekusi operasi `enqueue()` berdasarkan hasil pengecekan.\\n\\n**Petunjuk Memahami Soal**\\n1.  Perhatikan dengan seksama bagaimana Anda akan memeriksa apakah antrian sudah `penuh`. Ini adalah kondisi kunci.\\n2.  Pikirkan langkah-langkah *sebelum* dan *sesudah* memanggil operasi `enqueue()`.\\n3.  Pastikan Anda membedakan antara variabel yang menyimpan data pelanggan (`string`) dan struktur antrian itu sendiri (`queue` atau `string[]`).\\n4.  Ingat bahwa `enqueue()` hanya bisa dilakukan jika ada ruang.\", \"created_at\": \"2026-04-16 05:46:02\"}], \"access_id\": \"019d94d2-f2c0-735a-adaa-2d7e958b56b4\", \"waktu_detik\": 43, \"durasi_detik\": 24, \"triggered_at\": \"2026-04-16 05:46:02\", \"jumlah_langkah\": 24, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-16 05:46:09\", \"popup_opened_at\": \"2026-04-16 05:45:45\", \"waktu_akses_detik\": 43, \"waktu_detik_saat_close\": 68}', '2026-04-15 22:46:02', '2026-04-15 22:46:10', NULL),
('019d94e0-9446-729a-ab54-06364501d17b', '49b08ebe-e0c1-4f80-b21f-a425cbdab5b2', '244107020194', 'GILANG BAYU IRWANA', '019873da-b95c-7218-80ca-086512e0c5a1', 'TI-1F', '019863c4-59f9-7319-9104-08267fc3c551', 'Queue', '01996b09-9329-7208-be28-2b82f0987b22', 'Menambah Antrian', 25, '2026-04-15 22:59:50', '2026-04-15 23:01:02', NULL, 'Gaming the System', 0, 1, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-16 13:00:39 WIB\", \"respons\": \"Maaf, saya sedang tidak dapat merespons saat ini. Silakan coba lagi.\", \"created_at\": \"2026-04-16 06:00:39\"}], \"access_id\": \"019d94e0-7a2b-72e9-ba93-9479bc2482d4\", \"waktu_detik\": 42, \"durasi_detik\": 30, \"triggered_at\": \"2026-04-16 06:00:39\", \"jumlah_langkah\": 25, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-16 06:01:02\", \"popup_opened_at\": \"2026-04-16 06:00:32\", \"waktu_akses_detik\": 42, \"waktu_detik_saat_close\": 72}', '2026-04-15 23:00:39', '2026-04-15 23:01:02', NULL),
('019d94f5-3b22-73de-adbe-1e0f265291cf', 'c593831e-cdaa-4896-8726-71a2fb38d13f', '244107060072', 'ILHAN SALIH ILMANSYAH', '01997051-0d1a-7091-8ec0-d181c7bbf04b', 'SIB-1D', '019863c4-59f9-7319-9104-08267fc3c551', 'Queue', '01996b09-9329-7208-be28-2b82f0987b22', 'Menambah Antrian', 23, '2026-04-15 23:21:49', '2026-04-15 23:25:20', NULL, 'Struggling', 2, 1, '[ADAPTIVE - Struggling] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Struggling] Bimbingan materi otomatis\", \"waktu\": \"2026-04-16 13:23:12 WIB\", \"respons\": \"Halo! Mari kita pahami soal \\\"Menambah Antrian\\\" ini bersama.\\n\\n**Penjelasan Soal**\\nTujuan soal ini adalah membuat pseudocode untuk menambahkan pelanggan baru ke dalam antrian (`Queue`), dengan memastikan antrian tidak penuh terlebih dahulu.\\n\\n**Tipe Data**\\n*   **string[]**: Digunakan untuk menyimpan daftar pelanggan dalam antrian.\\n*   **string**: Untuk nama pelanggan baru yang akan ditambahkan.\\n*   **int**: Untuk ukuran antrian atau kapasitas maksimumnya.\\n\\n**Kondisi**\\n*   **IF-ELSE**: Digunakan untuk membuat keputusan. Di sini, untuk memeriksa apakah antrian sudah penuh atau belum.\\n\\n**Queue**\\n*   **Queue**: Struktur data yang mengikuti prinsip \\\"First-In, First-Out\\\" (FIFO), seperti antrian di restoran. Pelanggan pertama masuk, pertama dilayani.\\n*   **enqueue()**: Operasi untuk menambahkan elemen baru ke bagian belakang (akhir) antrian.\\n\\n**Algoritma**\\n1.  Definisikan fungsi untuk menambahkan pelanggan.\\n2.  Periksa apakah antrian sudah mencapai kapasitas maksimumnya.\\n3.  Jika penuh, berikan pesan bahwa antrian tidak bisa ditambah.\\n4.  Jika tidak penuh, tambahkan pelanggan baru menggunakan `enqueue()`.\\n\\n**Petunjuk Memahami Soal**\\n1.  Pikirkan apa yang harus menjadi langkah *pertama* saat ingin menambahkan sesuatu ke antrian.\\n2.  Bagaimana cara kita tahu jika antrian *penuh* atau *tidak*?\\n3.  Jika antrian penuh, apa yang harus kita lakukan? Pesan apa yang perlu ditampilkan?\\n4.  Jika antrian *tidak* penuh, bagaimana cara menambahkan pelanggan baru ke antrian? Operasi apa yang digunakan?\", \"created_at\": \"2026-04-16 06:23:12\"}], \"access_id\": \"019d94f5-15e8-71ec-8af3-5cb45ff1c210\", \"waktu_detik\": 72, \"durasi_detik\": 138, \"triggered_at\": \"2026-04-16 06:23:12\", \"jumlah_langkah\": 23, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-16 06:25:20\", \"popup_opened_at\": \"2026-04-16 06:23:02\", \"waktu_akses_detik\": 72, \"waktu_detik_saat_close\": 211}', '2026-04-15 23:23:12', '2026-04-15 23:25:21', NULL),
('019d950c-16ec-709c-8705-d396e753d00d', '18760fd9-69c2-42cd-8f21-45014788d18b', '244107060014', 'FEARENT AURELLIA PERMATA SARI', '01997051-0d1a-7091-8ec0-d181c7bbf04b', 'SIB-1D', '01995dec-678e-70cf-854a-b25e2c2d0d28', 'Tipe Data', '01995df6-35ed-7363-9d42-578622c3e4f2', 'Program Hitung Harga Motor', 20, '2026-04-15 23:47:07', '2026-04-15 23:48:36', NULL, 'Gaming the System', 0, 1, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-16 13:48:10 WIB\", \"respons\": \"Tentu, mari kita bedah soal ini.\\n\\n**Penjelasan Soal**\\nSoal ini meminta Anda untuk menghitung total uang yang harus dibayar Pak Hari setelah menambahkan pajak penjualan ke harga sepeda motor.\\n\\n**Tipe Data**\\n*   **double**: Digunakan untuk angka dengan desimal dan presisi tinggi, cocok untuk nilai uang atau persentase yang mungkin menghasilkan desimal.\\n*   **int**: Digunakan untuk bilangan bulat (tidak ada desimal).\\n*   **float**: Mirip dengan **double** untuk angka desimal, namun umumnya dengan presisi yang lebih rendah. Pikirkan kapan presisi tinggi penting.\\n\\n**Algoritma**\\n*   Inisialisasi variabel untuk harga motor dan persentase pajak.\\n*   Hitung jumlah pajak berdasarkan harga motor.\\n*   Tambahkan jumlah pajak ke harga motor untuk mendapatkan total bayar.\\n\\n**Petunjuk Memahami Soal**\\n1.  Identifikasi setiap angka yang ada di soal. Apakah ia bilangan bulat atau bisa memiliki nilai desimal?\\n2.  Pertimbangkan dengan cermat tipe data apa yang paling tepat untuk setiap nilai (harga, pajak, total) untuk menghindari pembulatan yang tidak diinginkan.\\n3.  Pecah perhitungan menjadi langkah-langkah kecil: pertama hitung pajak, lalu hitung total.\\n4.  Periksa logika dan tipe data di setiap langkah sebelum melanjutkan ke langkah berikutnya, jangan terburu-buru.\", \"created_at\": \"2026-04-16 06:48:10\"}], \"access_id\": \"019d950b-ec9c-730a-941e-10e708fda0ec\", \"waktu_detik\": 52, \"durasi_detik\": 37, \"triggered_at\": \"2026-04-16 06:48:10\", \"jumlah_langkah\": 20, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-16 06:48:36\", \"popup_opened_at\": \"2026-04-16 06:47:59\", \"waktu_akses_detik\": 52, \"waktu_detik_saat_close\": 89}', '2026-04-15 23:48:10', '2026-04-15 23:48:36', NULL),
('019d9529-ad97-7212-a240-2d032f09aa14', '14330e34-ed0f-40dc-938e-a807cdaa80f2', '244107020071', 'LOUIS JUDIA B SINAGA', '019873da-b95c-7218-80ca-086512e0c5a1', 'TI-1F', '019863c4-59f9-7319-9104-08267fc3c551', 'Queue', '01996b09-9329-7208-be28-2b82f0987b22', 'Menambah Antrian', 24, '2026-04-16 00:19:20', '2026-04-16 00:23:37', NULL, 'Struggling', 3, 1, '[ADAPTIVE - Struggling] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Struggling] Bimbingan materi otomatis\", \"waktu\": \"2026-04-16 14:20:29 WIB\", \"respons\": \"**Penjelasan Soal**\\nTujuan soal ini adalah membuat pseudocode untuk menambahkan pelanggan baru ke antrian, tetapi hanya jika antrian tersebut belum penuh.\\n\\n**Tipe Data**\\n*   **string[]**: Digunakan untuk menyimpan daftar nama pelanggan yang ada dalam antrian.\\n*   **string**: Untuk menyimpan satu nama pelanggan yang akan ditambahkan.\\n*   **int**: Digunakan untuk melacak ukuran atau kapasitas antrian.\\n\\n**Kondisi**\\n*   Akan ada kondisi `IF` untuk memeriksa apakah antrian sudah mencapai kapasitas maksimumnya sebelum menambahkan elemen.\\n\\n**Fungsi**\\n*   Akan ada fungsi `enqueue()` yang digunakan untuk menambahkan elemen ke antrian, dan mungkin fungsi `isFull()` untuk memeriksa apakah antrian penuh.\\n\\n**Queue**\\n*   **Queue** adalah struktur data yang mengikuti prinsip \\\"First-In, First-Out\\\" (FIFO), artinya elemen yang pertama masuk akan pertama keluar.\\n\\n**Algoritma**\\n*   Definisikan sebuah fungsi untuk menambahkan pelanggan baru ke antrian.\\n*   Di dalam fungsi, periksa dulu apakah antrian telah mencapai batas kapasitasnya.\\n*   Jika antrian belum penuh, tambahkan pelanggan ke bagian akhir antrian.\\n\\n**Petunjuk Memahami Soal**\\n1.  Bayangkan antrian sebagai barisan orang. Orang baru selalu berdiri di paling belakang.\\n2.  Pikirkan bagaimana cara mengetahui jika barisan itu sudah terlalu panjang dan tidak bisa menampung orang lagi.\\n3.  Gunakan struktur `IF...THEN...ELSE` untuk dua kemungkinan: antrian penuh atau antrian masih ada ruang.\\n4.  Operasi `enqueue()` berarti menempatkan elemen baru di posisi paling belakang dalam **Queue**.\", \"created_at\": \"2026-04-16 07:20:29\"}], \"access_id\": \"019d9529-8e10-72cf-9fc2-828a1f7224ef\", \"waktu_detik\": 61, \"durasi_detik\": 196, \"triggered_at\": \"2026-04-16 07:20:29\", \"jumlah_langkah\": 24, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-16 07:23:37\", \"popup_opened_at\": \"2026-04-16 07:20:21\", \"waktu_akses_detik\": 61, \"waktu_detik_saat_close\": 257}', '2026-04-16 00:20:29', '2026-04-16 00:23:37', NULL),
('019d9588-f795-7136-a62c-de9b4800a4fb', '019bd119-feea-72db-ae7f-6eab643a243d', '2241760023', 'Mochammad Dicky Hanun Prasetyo', '01984a60-f7eb-737d-a267-6afadbf35e7e', 'TI-1C', '019863c4-59f9-7319-9104-08267fc3c551', 'Queue', '01996b09-9329-7208-be28-2b82f0987b22', 'Menambah Antrian', 19, '2026-04-16 02:03:07', '2026-04-16 02:05:34', NULL, 'Struggling', 1, 67, '[ADAPTIVE - Struggling] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Struggling] Bimbingan materi otomatis\", \"waktu\": \"2026-04-16 16:04:34 WIB\", \"respons\": \"Maaf, saya sedang tidak dapat merespons saat ini. Silakan coba lagi.\", \"created_at\": \"2026-04-16 09:04:34\"}], \"access_id\": \"019d9588-ec72-707d-a438-26fd1fdef6a5\", \"waktu_detik\": 83, \"durasi_detik\": 63, \"triggered_at\": \"2026-04-16 09:04:34\", \"jumlah_langkah\": 19, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-16 09:05:34\", \"popup_opened_at\": \"2026-04-16 09:04:31\", \"waktu_akses_detik\": 83, \"waktu_detik_saat_close\": 147}', '2026-04-16 02:04:34', '2026-04-16 02:05:35', NULL),
('019d9ec4-78b8-71cf-ac62-6f4da846a8c2', '406036aa-6d0a-4e6e-ab7c-b34ff78180b0', '244107020197', 'JONATHAN DWI PANGESTU', '019873da-b95c-7218-80ca-086512e0c5a1', 'TI-1F', '01995dec-678e-70cf-854a-b25e2c2d0d28', 'Tipe Data', '01995df6-35ed-7363-9d42-578622c3e4f2', 'Program Hitung Harga Motor', 20, '2026-04-17 21:03:25', '2026-04-17 21:06:22', NULL, 'Struggling', 0, 1, '[ADAPTIVE - Struggling] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Struggling] Bimbingan materi otomatis\", \"waktu\": \"2026-04-18 11:06:09 WIB\", \"respons\": \"**Penjelasan Soal**\\nSoal ini meminta Anda menghitung total uang yang harus dibayar Pak Hari setelah harga motor ditambah pajak penjualan.\\n\\n**Tipe Data**\\n- **int**: Untuk bilangan bulat, misalnya angka 10 (dari 10%).\\n- **float**: Untuk bilangan desimal dengan presisi standar, cocok untuk harga atau nilai pajak.\\n- **double**: Mirip **float**, namun dengan presisi lebih tinggi, ideal untuk perhitungan uang agar akurat.\\n\\n**Algoritma**\\n- Algoritma adalah urutan langkah logis untuk menyelesaikan masalah.\\n- Anda perlu mengidentifikasi input, proses perhitungan, dan output yang diinginkan.\\n\\n**Petunjuk Memahami Soal**\\n1.  Identifikasi nilai awal yang diketahui (harga motor, persentase pajak).\\n2.  Pikirkan: apa yang perlu dihitung pertama kali? (Jumlah pajak dalam rupiah).\\n3.  Lalu, bagaimana cara menghitung total harga yang harus dibayar?\\n4.  Tentukan tipe data yang paling cocok untuk menyimpan setiap nilai.\", \"created_at\": \"2026-04-18 04:06:09\"}], \"access_id\": \"019d9ec4-528b-7394-993f-68edcd29a9d2\", \"waktu_detik\": 177, \"durasi_detik\": 23, \"triggered_at\": \"2026-04-18 04:06:09\", \"jumlah_langkah\": 20, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-18 04:06:22\", \"popup_opened_at\": \"2026-04-18 04:05:59\", \"attempt_start_at\": \"2026-04-18 04:03:25\", \"waktu_akses_detik\": 177, \"waktu_detik_saat_close\": 177}', '2026-04-17 21:06:09', '2026-04-28 08:36:39', NULL),
('019d9eec-81ef-731d-91e3-3dff93579ac6', '7b34a8be-9343-43a8-9ee9-bd748e75f148', '244107020010', 'MOCHAMMAD FAISOL BISMAGRAHA', '019873da-b95c-7218-80ca-086512e0c5a1', 'TI-1F', '019863c4-59f9-7319-9104-08267fc3c551', 'Queue', '01996b09-9329-7208-be28-2b82f0987b22', 'Menambah Antrian', 21, '2026-04-17 21:48:59', '2026-04-17 21:50:36', NULL, 'Gaming the System', 0, 1, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-18 11:49:53 WIB\", \"respons\": \"Tentu, mari kita pahami soal ini bersama.\\n\\n**Penjelasan Soal**\\nTujuan soal ini adalah membuat pseudocode untuk menambahkan data pelanggan baru ke dalam antrian (**Queue**) menggunakan operasi `enqueue()`, dengan pengecekan apakah antrian sudah penuh terlebih dahulu.\\n\\n**Tipe Data**\\n*   **string[]**: Tipe data ini adalah array yang berisi kumpulan **string**. Digunakan untuk menyimpan daftar nama atau informasi teks.\\n*   **string**: Tipe data ini adalah urutan karakter tunggal. Digunakan untuk menyimpan nama pelanggan atau informasi teks lainnya.\\n*   **int**: Tipe data ini adalah bilangan bulat. Biasanya digunakan untuk menghitung jumlah atau indeks.\\n*   **char[]**: Tipe data ini adalah array yang berisi kumpulan **char**. Mirip dengan **string** tetapi diakses per karakter.\\n*   **char**: Tipe data ini adalah karakter tunggal.\\n\\n**Queue**\\n*   **Queue** adalah struktur data yang bekerja dengan prinsip FIFO (First-In, First-Out). Elemen yang pertama masuk akan menjadi yang pertama keluar.\\n*   Operasi `enqueue()` digunakan untuk menambahkan elemen baru ke bagian belakang antrian.\\n\\n**Kondisi**\\n*   **IF**: Digunakan untuk membuat keputusan. Dalam soal ini, Anda perlu menggunakan `IF` untuk memeriksa apakah antrian sudah dalam kondisi penuh.\\n\\n**Algoritma**\\n1.  Menerima data pelanggan baru yang akan ditambahkan.\\n2.  Melakukan pengecekan kondisi antrian: apakah sudah penuh atau belum.\\n3.  Jika antrian tidak penuh, tambahkan pelanggan ke antrian.\\n\\n**Petunjuk Memahami Soal**\\n1.  **Perhatikan Detail Tipe Data**: Teliti perbedaan antara **string**, **string[]**, **char**, dan **char[]**. Kapan Anda perlu menyimpan satu nama (string), dan kapan daftar nama (string[])?\\n2.  **Prioritas Pengecekan**: Ingat, operasi `enqueue()` hanya boleh dilakukan *setelah* antrian dipastikan tidak penuh. Bagaimana pseudocode menunjukkan urutan ini?\\n3.  **Fungsi Queue**: Pahami bahwa `enqueue()` hanya menambahkan; ia tidak memeriksa kondisi penuh. Kondisi penuh adalah logika yang harus Anda tambahkan sendiri.\\n4.  **Representasi \\\"Penuh\\\"**: Pikirkan bagaimana pseudocode akan mengekspresikan kondisi \\\"antrian penuh\\\". Apakah ada fungsi khusus atau variabel yang perlu diperiksa?\", \"created_at\": \"2026-04-18 04:49:53\"}], \"access_id\": \"019d9eec-5bda-7271-a8c6-ac7cd7839453\", \"waktu_detik\": 43, \"durasi_detik\": 54, \"triggered_at\": \"2026-04-18 04:49:53\", \"jumlah_langkah\": 21, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-18 04:50:36\", \"popup_opened_at\": \"2026-04-18 04:49:42\", \"attempt_start_at\": \"2026-04-18 04:48:59\", \"waktu_akses_detik\": 43, \"waktu_detik_saat_close\": 96}', '2026-04-17 21:49:53', '2026-04-17 21:50:37', NULL),
('019d9efa-ba5d-72a8-b9ac-86b553b23c8b', '019bd119-feea-72db-ae7f-6eab643a243d', '2241760023', 'Mochammad Dicky Hanun Prasetyo', '01984a60-f7eb-737d-a267-6afadbf35e7e', 'TI-1C', '019863c4-59f9-7319-9104-08267fc3c551', 'Queue', '01996b09-9329-7208-be28-2b82f0987b22', 'Menambah Antrian', 22, '2026-04-17 22:04:24', '2026-04-17 22:06:27', NULL, 'Gaming the System', 1, 68, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-18 12:05:25 WIB\", \"respons\": \"Halo! Mari kita pahami soal \\\"Menambah Antrian\\\" ini dengan lebih teliti.\\n\\n**Penjelasan Soal**\\nSoal ini meminta Anda untuk membuat pseudocode yang menambahkan pelanggan baru ke dalam sebuah antrian (`Queue`), dengan syarat harus memeriksa apakah antrian sudah penuh terlebih dahulu.\\n\\n**Tipe Data**\\n*   **string**: Akan digunakan untuk menyimpan nama pelanggan baru.\\n*   **int**: Mungkin diperlukan untuk melacak ukuran atau kapasitas antrian, terutama saat memeriksa apakah antrian penuh.\\n*   **Queue**: Struktur data utama yang menyimpan urutan pelanggan.\\n\\n**Kondisi**\\n*   **IF**: Anda perlu menggunakan kondisi `IF` untuk memeriksa apakah antrian sudah penuh (`isFull()`) sebelum melakukan operasi penambahan.\\n\\n**Fungsi**\\n*   **enqueue()**: Operasi standar untuk menambahkan elemen ke belakang antrian.\\n*   **isFull()**: Fungsi yang akan memeriksa apakah antrian sudah mencapai kapasitas maksimumnya.\\n\\n**Queue**\\n*   **Queue**: Adalah struktur data FIFO (First-In, First-Out) di mana elemen ditambahkan di belakang (enqueue) dan dihapus dari depan (dequeue).\\n\\n**Algoritma**\\n*   Menerima data pelanggan baru.\\n*   Memeriksa status antrian (penuh atau tidak).\\n*   Melakukan operasi penambahan jika memungkinkan.\\n\\n**Petunjuk Memahami Soal**\\n1.  Pikirkan langkah pertama yang *harus* dilakukan sebelum menambahkan pelanggan. Apa itu?\\n2.  Bagaimana cara Anda merepresentasikan \\\"pelanggan baru\\\" dalam pseudocode?\\n3.  Perhatikan urutan operasi: \\\"memeriksa *sebelum* menambah\\\". Ini krusial.\\n4.  Apa yang terjadi jika antrian penuh? Apakah ada pesan yang perlu ditampilkan?\", \"created_at\": \"2026-04-18 05:05:25\"}], \"access_id\": \"019d9efa-9dd5-7172-bfac-6a08be569708\", \"waktu_detik\": 122, \"durasi_detik\": 70, \"triggered_at\": \"2026-04-18 05:05:25\", \"jumlah_langkah\": 22, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-18 05:06:27\", \"popup_opened_at\": \"2026-04-18 05:05:17\", \"attempt_start_at\": \"2026-04-18 05:04:24\", \"waktu_akses_detik\": 122, \"waktu_detik_saat_close\": 122}', '2026-04-17 22:05:25', '2026-04-17 22:06:27', NULL),
('019d9f00-162e-7343-afd7-ad2d13824fe9', '01998481-df25-70a6-8d69-3fee01558a4c', '2141720101', 'Muhammad Bintang Sholu Firmansyah', '01984a60-f7eb-737d-a267-6afadbf35e7e', 'TI-1C', '01995dec-678e-70cf-854a-b25e2c2d0d28', 'Tipe Data', '01995df6-35ed-7363-9d42-578622c3e4f2', 'Program Hitung Harga Motor', 22, '2026-04-17 22:10:33', '2026-04-17 22:11:53', NULL, 'Gaming the System', 0, 5, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-18 12:11:16 WIB\", \"respons\": \"**Penjelasan Soal**\\nSoal ini meminta Anda menghitung total biaya pembelian motor setelah ditambahkan pajak penjualan.\\n\\n**Tipe Data**\\n*   **int**: Digunakan untuk bilangan bulat (tanpa desimal).\\n*   **float**: Digunakan untuk bilangan desimal dengan presisi tunggal.\\n*   **double**: Digunakan untuk bilangan desimal dengan presisi ganda, lebih akurat dari **float** untuk nilai uang yang besar.\\n\\n**Algoritma**\\n*   Inisialisasi harga motor.\\n*   Hitung nilai pajak dari harga motor.\\n*   Jumlahkan harga motor dan pajak untuk mendapatkan total pembayaran.\\n\\n**Petunjuk Memahami Soal**\\n1.  Perhatikan perbedaan antara **int**, **float**, dan **double** dalam menangani angka desimal dan presisi.\\n2.  Pikirkan langkah-langkah perhitungan secara berurutan: mana yang harus dihitung terlebih dahulu?\\n3.  Pertimbangkan apakah hasil perhitungan pajak akan selalu bilangan bulat atau bisa desimal.\\n4.  Jangan terburu-buru, pahami alasan di balik setiap pilihan tipe data Anda.\", \"created_at\": \"2026-04-18 05:11:16\"}, {\"waktu\": \"2026-04-18 12:11:40 WIB\", \"source\": \"adaptive_conversation\", \"bot_name\": \"PseudoLearn Chatbot AI\", \"access_id\": \"019d9eff-f219-708e-8cde-7ef75442dba6\", \"created_at\": \"2026-04-18 05:11:40\", \"bot_response\": \"Halo! Selamat datang di PseudoLearn. Saya di sini untuk membantu kamu memahami konsep pemrograman, bukan memberikan jawaban langsung dari soal, ya. Tujuanku adalah membimbing kamu agar bisa menemukan solusi sendiri dan mengerti proses berpikirnya.\\n\\n**Memahami Soal Algoritma**\\nUntuk bisa membantu kamu, mari kita mulai dengan memahami soalnya terlebih dahulu. Setiap algoritma pasti akan bekerja dengan *data*. Nah, pada level \\\"Tipe Data\\\" ini, langkah pertama yang sangat penting adalah mengidentifikasi jenis data apa saja yang akan kamu tangani dalam algoritma tersebut.\\n\\n**Pertanyaan Pemandu untuk Memulai:**\\nCoba kamu ceritakan sedikit tentang soal yang sedang kamu kerjakan. Misalnya:\\n*   Data apa yang akan menjadi *input* untuk algoritma ini? Apakah itu angka, teks, true/false, atau sesuatu yang lain?\\n*   Apa yang diharapkan menjadi *output* dari algoritma ini? Bentuknya seperti apa?\\n*   Operasi apa yang kira-kira akan dilakukan pada data tersebut? (Contoh: penjumlahan, perbandingan, penggabungan teks, dll.)\\n\\nDengan mengetahui hal-hal ini, kita bisa mulai berpikir tentang **tipe data** yang paling cocok untuk menyimpan dan memanipulasi informasi tersebut. Memilih tipe data yang tepat adalah fondasi penting dalam membangun algoritma yang efisien dan benar!\", \"mahasiswa_name\": \"Muhammad Bintang Sholu Firmansyah\", \"mahasiswa_message\": \"bagaimana jawaban algoritma untuk soal tersebut?\"}], \"access_id\": \"019d9eff-f219-708e-8cde-7ef75442dba6\", \"waktu_detik\": 79, \"durasi_detik\": 47, \"triggered_at\": \"2026-04-18 05:11:16\", \"jumlah_langkah\": 22, \"total_messages\": 2, \"popup_closed_at\": \"2026-04-18 05:11:53\", \"popup_opened_at\": \"2026-04-18 05:11:06\", \"attempt_start_at\": \"2026-04-18 05:10:33\", \"waktu_akses_detik\": 79, \"waktu_detik_saat_close\": 79}', '2026-04-17 22:11:16', '2026-04-17 22:11:53', NULL),
('019d9f79-ffed-719d-9ad1-759345cad548', '9f2c131a-c213-4c2f-9716-60bfb07108ea', '244107020061', 'MUHAMMAD DANIEL ASSAQOVI', '019873da-b95c-7218-80ca-086512e0c5a1', 'TI-1F', '01995dec-678e-70cf-854a-b25e2c2d0d28', 'Tipe Data', '01995df6-35ed-7363-9d42-578622c3e4f2', 'Program Hitung Harga Motor', 20, '2026-04-18 00:23:32', '2026-04-18 00:24:24', NULL, 'Gaming the System', 0, 1, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-18 14:24:25 WIB\", \"respons\": \"**Penjelasan Soal**\\nSoal ini meminta Anda menghitung total uang yang harus dibayar Pak Hari setelah harga motor ditambahkan dengan pajak penjualan.\\n\\n**Tipe Data**\\n*   **int**: Digunakan untuk bilangan bulat tanpa desimal, seperti jumlah unit barang.\\n*   **float**: Digunakan untuk bilangan desimal dengan presisi tunggal. Cocok untuk nilai mata uang atau persentase.\\n*   **double**: Mirip dengan float, tetapi memiliki presisi ganda. Lebih akurat untuk perhitungan yang membutuhkan ketelitian tinggi.\\n\\n**Algoritma**\\n*   Inisialisasi variabel untuk harga motor dan persentase pajak.\\n*   Hitung jumlah pajak berdasarkan persentase dan harga motor.\\n*   Jumlahkan harga motor dengan jumlah pajak untuk mendapatkan total harga.\\n\\n**Petunjuk Memahami Soal**\\n1.  Pikirkan mengapa ada tiga tipe data (`int`, `float`, `double`) yang disebutkan. Apa perbedaan dan kapan masing-masing paling cocok digunakan untuk nilai uang dan persentase?\\n2.  Perhatikan urutan operasi. Apa yang harus dihitung terlebih dahulu: pajak atau total harga?\\n3.  Fokus pada setiap langkah perhitungan secara berurutan. Hindari melompati langkah atau menebak hasilnya.\\n4.  Pastikan Anda memahami bagaimana persentase diubah menjadi angka desimal dalam perhitungan.\", \"created_at\": \"2026-04-18 07:24:25\"}], \"access_id\": \"019d9f79-da77-7233-9a50-d3fefe8dd5f0\", \"waktu_detik\": 51, \"durasi_detik\": 8, \"triggered_at\": \"2026-04-18 07:24:25\", \"jumlah_langkah\": 20, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-18 07:24:24\", \"popup_opened_at\": \"2026-04-18 07:24:16\", \"attempt_start_at\": \"2026-04-18 07:23:32\", \"waktu_akses_detik\": 51, \"waktu_detik_saat_close\": 51}', '2026-04-18 00:24:25', '2026-04-18 00:24:26', NULL),
('019d9f88-eae3-7395-80ec-6fa48a790ed4', 'f5c2431c-5728-4cde-872a-ee8ac7a31be3', '244107020198', 'MOKHAMAD RIZKI HADIONO SINGGIH', '019873da-b95c-7218-80ca-086512e0c5a1', 'TI-1F', '019863c4-59f9-7319-9104-08267fc3c551', 'Queue', '01996b09-9329-7208-be28-2b82f0987b22', 'Menambah Antrian', 20, '2026-04-18 00:39:53', '2026-04-18 00:40:53', NULL, 'Gaming the System', 0, 1, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-18 14:40:43 WIB\", \"respons\": \"Halo! Mari kita bedah soal \\\"Menambah Antrian\\\" pada level Queue ini.\\n\\n**Penjelasan Soal**\\nSoal ini bertujuan membuat pseudocode untuk menambahkan pelanggan baru ke dalam antrian (Queue) menggunakan operasi `enqueue()`, dengan memastikan antrian tidak penuh terlebih dahulu.\\n\\n**Tipe Data**\\n*   **string**: Digunakan untuk menyimpan nama pelanggan baru.\\n*   **string[]**: Sebuah array dari **string**, bisa jadi untuk representasi antrian itu sendiri jika diimplementasikan sebagai array.\\n*   **int**: Digunakan untuk ukuran antrian, indeks, atau jumlah elemen.\\n*   **char[]**: Array dari **char**, biasanya untuk teks atau string yang dipecah per karakter.\\n*   **char**: Sebuah karakter tunggal.\\n\\n**Queue**\\n*   **Queue**: Struktur data yang mengikuti prinsip FIFO (First-In, First-Out).\\n*   `enqueue()`: Operasi untuk menambahkan elemen baru ke bagian belakang antrian.\\n*   `isFull()`: Operasi untuk memeriksa apakah antrian sudah penuh.\\n\\n**Kondisi**\\n*   **IF-ELSE**: Digunakan untuk membuat keputusan, dalam kasus ini, memeriksa apakah antrian penuh sebelum melakukan penambahan.\\n\\n**Algoritma**\\n*   Mendefinisikan antrian dan pelanggan baru.\\n*   Memeriksa apakah antrian sudah mencapai kapasitas maksimum.\\n*   Menambahkan pelanggan jika antrian belum penuh.\\n\\n**Petunjuk Memahami Soal**\\n1.  Fokus pada konsep dasar **Queue**: Bagaimana `enqueue()` bekerja dan apa artinya \\\"antrian penuh\\\".\\n2.  Perhatikan urutan logika: Apakah Anda memeriksa kondisi antrian *sebelum* atau *sesudah* mencoba menambahkan pelanggan?\\n3.  Pikirkan tentang **tipe data** `string` untuk pelanggan baru dan bagaimana ia akan masuk ke **Queue**.\\n4.  Identifikasi dua kemungkinan hasil: berhasil menambah atau antrian penuh.\", \"created_at\": \"2026-04-18 07:40:43\"}], \"access_id\": \"019d9f88-d004-7127-aaee-62f1e538fb89\", \"waktu_detik\": 59, \"durasi_detik\": 17, \"triggered_at\": \"2026-04-18 07:40:43\", \"jumlah_langkah\": 20, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-18 07:40:53\", \"popup_opened_at\": \"2026-04-18 07:40:36\", \"attempt_start_at\": \"2026-04-18 07:39:53\", \"waktu_akses_detik\": 59, \"waktu_detik_saat_close\": 59}', '2026-04-18 00:40:43', '2026-04-18 00:40:53', NULL),
('019d9f9e-610c-7092-958e-4e367fdb703b', '773dab04-30a2-4eb9-91d5-19e5f62226ab', '244107020121', 'MUHAMMAD FATAHILLAH ATHABRANI', '019873da-b95c-7218-80ca-086512e0c5a1', 'TI-1F', '019863c4-59f9-7319-9104-08267fc3c551', 'Queue', '01996b09-9329-7208-be28-2b82f0987b22', 'Menambah Antrian', 19, '2026-04-18 01:02:56', '2026-04-18 01:04:31', NULL, 'Struggling', 0, 1, '[ADAPTIVE - Struggling] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Struggling] Bimbingan materi otomatis\", \"waktu\": \"2026-04-18 15:04:10 WIB\", \"respons\": \"**Penjelasan Soal**\\nBuat pseudocode untuk menambahkan pelanggan baru ke antrian, sambil memastikan antrian tidak penuh.\\n\\n**Tipe Data**\\n*   **string**: Digunakan untuk menyimpan nama pelanggan.\\n*   **string[]**: Digunakan sebagai representasi antrian pelanggan.\\n*   **int**: Digunakan untuk menyimpan kapasitas antrian dan jumlah elemen saat ini.\\n\\n**Kondisi**\\n*   **IF**: Digunakan untuk memeriksa apakah antrian sudah mencapai kapasitas maksimumnya sebelum menambahkan pelanggan.\\n\\n**Queue**\\n*   Queue (Antrian): Struktur data \\\"First-In, First-Out\\\" (FIFO). Elemen pertama masuk adalah yang pertama keluar.\\n\\n**Algoritma**\\n*   Siapkan antrian dan kapasitasnya.\\n*   Dapatkan nama pelanggan baru.\\n*   Periksa apakah antrian memiliki ruang.\\n*   Jika ya, tambahkan pelanggan.\\n\\n**Petunjuk Memahami Soal**\\n1.  Pikirkan cara **mendeklarasikan** antrian dan kapasitas maksimumnya.\\n2.  Bagaimana cara **mengambil** nama pelanggan baru dari input?\\n3.  Bagaimana Anda **memeriksa** kondisi \\\"antrian penuh\\\"?\\n4.  Gunakan operasi **enqueue()** untuk menambahkan elemen ke antrian.\", \"created_at\": \"2026-04-18 08:04:10\"}], \"access_id\": \"019d9f9e-3a71-72b2-ac00-4fed3923b3ba\", \"waktu_detik\": 94, \"durasi_detik\": 31, \"triggered_at\": \"2026-04-18 08:04:10\", \"jumlah_langkah\": 19, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-18 08:04:31\", \"popup_opened_at\": \"2026-04-18 08:04:00\", \"attempt_start_at\": \"2026-04-18 08:02:56\", \"waktu_akses_detik\": 94, \"waktu_detik_saat_close\": 94}', '2026-04-18 01:04:10', '2026-04-18 01:04:31', NULL),
('019d9fa2-a72b-70a5-a559-5a0bb80ba36f', '7306a1f7-b22a-4ca9-874f-9ea33c5623b6', '244107020191', 'SHARREN ELVARETTA PRATAMADYA FIANTO', '019873da-b95c-7218-80ca-086512e0c5a1', 'TI-1F', '019863c4-59f9-7319-9104-08267fc3c551', 'Queue', '01996b09-9329-7208-be28-2b82f0987b22', 'Menambah Antrian', 22, '2026-04-18 01:08:09', '2026-04-18 01:10:26', NULL, 'Gaming the System', 1, 1, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-18 15:08:50 WIB\", \"respons\": \"Halo! Mari kita pahami soal \\\"Menambah Antrian\\\" ini.\\n\\n**Penjelasan Soal**\\nSoal ini meminta Anda membuat pseudocode untuk menambahkan pelanggan baru ke dalam antrian (**Queue**) dengan operasi `enqueue()`, sambil memastikan antrian tidak penuh.\\n\\n**Tipe Data**\\n*   **string[]**: Array yang berisi kumpulan **string**, mungkin digunakan untuk menyimpan banyak nama pelanggan atau data teks lainnya secara berurutan.\\n*   **string**: Tipe data untuk menyimpan teks, seperti nama pelanggan baru.\\n*   **int**: Tipe data untuk bilangan bulat, bisa digunakan untuk ukuran antrian atau indeks.\\n*   **char[]**: Array yang berisi kumpulan **char**, mungkin untuk menyimpan urutan karakter.\\n*   **char**: Tipe data untuk satu karakter tunggal, misalnya \'A\' atau \'1\'.\\n\\n**Kondisi**\\n*   **IF**: Digunakan untuk membuat keputusan, dalam kasus ini, memeriksa apakah antrian sudah penuh (`IsFull()`) sebelum menambahkan pelanggan.\\n\\n**Queue**\\n*   **Queue**: Struktur data yang mengikuti prinsip FIFO (First-In, First-Out). Elemen ditambahkan ke belakang (rear) dan dihapus dari depan (front).\\n*   `enqueue()`: Operasi untuk menambahkan elemen baru ke bagian belakang **Queue**.\\n\\n**Algoritma**\\n1.  Menerima input nama pelanggan baru.\\n2.  Memeriksa kondisi antrian, apakah sudah penuh atau belum.\\n3.  Jika tidak penuh, tambahkan pelanggan ke antrian.\\n4.  Jika penuh, berikan pesan bahwa antrian tidak bisa ditambahkan.\\n\\n**Petunjuk Memahami Soal**\\n1.  Pikirkan bagaimana cara mendapatkan \\\"pelanggan baru\\\" sebagai **string**.\\n2.  Ingat bahwa `enqueue()` hanya bisa dilakukan jika **Queue** belum penuh. Jadi, **kondisi** `IsFull()` adalah kunci.\\n3.  Perhatikan perbedaan antara `string` (nama pelanggan) dan `char` (satu huruf) agar tidak salah tipe data saat menambahkan.\\n4.  Susun langkah-langkahnya secara logis, mulai dari input hingga output hasil atau pesan kesalahan.\", \"created_at\": \"2026-04-18 08:08:50\"}], \"access_id\": \"019d9fa2-91a7-7181-b174-a73d13ad1b16\", \"waktu_detik\": 136, \"durasi_detik\": 102, \"triggered_at\": \"2026-04-18 08:08:50\", \"jumlah_langkah\": 22, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-18 08:10:26\", \"popup_opened_at\": \"2026-04-18 08:08:44\", \"attempt_start_at\": \"2026-04-18 08:08:09\", \"waktu_akses_detik\": 136, \"waktu_detik_saat_close\": 136}', '2026-04-18 01:08:50', '2026-04-18 01:10:26', NULL),
('019d9fa7-3efa-70dd-ab17-42d076e93467', '554de2ca-b80b-4d09-94ae-70158a754702', '244107020032', 'M. YAHYA IRVANSYAH', '019873da-b95c-7218-80ca-086512e0c5a1', 'TI-1F', '019863c4-59f9-7319-9104-08267fc3c551', 'Queue', '01996b09-9329-7208-be28-2b82f0987b22', 'Menambah Antrian', 22, '2026-04-18 01:13:06', '2026-04-18 01:14:02', NULL, 'Gaming the System', 0, 2, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-18 15:13:51 WIB\", \"respons\": \"Halo! Mari kita bahas soal \\\"Menambah Antrian\\\" ini agar kamu lebih teliti dalam menyusun pseudocode.\\n\\n**Penjelasan Soal**\\nTujuan soal adalah membuat pseudocode untuk menambahkan pelanggan baru ke **Queue**, memastikan antrian tidak penuh terlebih dahulu.\\n\\n**Tipe Data**\\n-   **string**: Untuk nama pelanggan baru.\\n-   **int**: Untuk ukuran atau kapasitas **Queue**.\\n\\n**Queue**\\n-   **Queue**: Struktur data FIFO (First-In, First-Out) untuk mengelola antrian pelanggan.\\n\\n**Kondisi**\\n-   Pengecekan penuh: Memverifikasi apakah **Queue** telah mencapai batas kapasitasnya.\\n\\n**Algoritma**\\n-   Definisikan prosedur penambahan.\\n-   Periksa kondisi **Queue** penuh.\\n-   Jika tidak penuh, tambahkan pelanggan (**enqueue**).\\n-   Jika penuh, berikan pesan.\\n\\n**Petunjuk Memahami Soal**\\n1.  Pahami *urutan* langkah: cek penuh, baru **enqueue**. Jangan sampai terbalik.\\n2.  Bagaimana pseudocode menyatakan kondisi \\\"antrian penuh\\\"? Pikirkan fungsi atau properti yang mungkin dimiliki **Queue**.\\n3.  Perhatikan *aksi* berbeda yang harus dilakukan untuk antrian penuh versus tidak penuh.\", \"created_at\": \"2026-04-18 08:13:51\"}], \"access_id\": \"019d9fa7-16c9-7096-8883-74e9b1ea6877\", \"waktu_detik\": 56, \"durasi_detik\": 22, \"triggered_at\": \"2026-04-18 08:13:51\", \"jumlah_langkah\": 22, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-18 08:14:02\", \"popup_opened_at\": \"2026-04-18 08:13:40\", \"attempt_start_at\": \"2026-04-18 08:13:06\", \"waktu_akses_detik\": 56, \"waktu_detik_saat_close\": 56}', '2026-04-18 01:13:51', '2026-04-18 01:14:02', NULL),
('019db35a-147d-700b-bbcc-0214d589ac8f', '93353d8c-5f0b-46a6-8599-054c96a3d2a0', '244107020118', 'MUHAMMAD HANIF', '019873da-b95c-7218-80ca-086512e0c5a1', 'TI-1F', '019863c4-59f9-7319-9104-08267fc3c551', 'Queue', '01996b09-9329-7208-be28-2b82f0987b22', 'Menambah Antrian', 19, '2026-04-21 21:00:25', '2026-04-21 21:22:59', NULL, 'Struggling', 21, 1, '[ADAPTIVE - Struggling] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Struggling] Bimbingan materi otomatis\", \"waktu\": \"2026-04-22 11:01:58 WIB\", \"respons\": \"Tentu, mari kita pahami soal ini bersama!\\n\\n**Penjelasan Soal**\\nTujuan soal ini adalah membuat pseudocode untuk menambahkan pelanggan baru ke dalam antrian restoran, dengan memastikan antrian tidak penuh terlebih dahulu.\\n\\n**Tipe Data**\\n*   **string[]**: Kumpulan **string** (teks) yang bisa digunakan untuk menyimpan daftar nama pelanggan dalam antrian.\\n*   **string**: Tipe data untuk menyimpan satu nama pelanggan baru (berupa teks).\\n*   **int**: Tipe data untuk bilangan bulat, sering digunakan untuk menghitung jumlah pelanggan atau kapasitas antrian.\\n\\n**Kondisi**\\n*   **IF**: Digunakan untuk memeriksa suatu kondisi. Dalam soal ini, untuk memeriksa apakah antrian sudah penuh atau belum.\\n\\n**Queue**\\n*   **Queue**: Struktur data yang mengikuti prinsip \\\"First-In, First-Out\\\" (FIFO), seperti antrian di kasir. Elemen pertama yang masuk akan keluar pertama.\\n*   **enqueue()**: Operasi untuk menambahkan elemen baru ke bagian belakang (akhir) antrian.\\n\\n**Algoritma**\\n*   Menerima data pelanggan baru.\\n*   Memeriksa apakah antrian memiliki ruang kosong.\\n*   Menambahkan pelanggan jika ada ruang.\\n\\n**Petunjuk Memahami Soal**\\n1.  Pikirkan langkah pertama: apa yang harus kita dapatkan (input) sebelum bisa menambahkan?\\n2.  Ingat bahwa ada syarat penting: antrian tidak boleh penuh. Bagaimana cara memeriksa ini?\\n3.  Jika antrian tidak penuh, operasi apa yang digunakan untuk memasukkan pelanggan?\\n4.  Apa yang terjadi jika antrian ternyata sudah penuh?\", \"created_at\": \"2026-04-22 04:01:58\"}], \"access_id\": \"019db359-f278-738c-af49-3afc62d6f8f7\", \"waktu_detik\": 1354, \"durasi_detik\": 1270, \"triggered_at\": \"2026-04-22 04:01:58\", \"jumlah_langkah\": 19, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-22 04:22:59\", \"popup_opened_at\": \"2026-04-22 04:01:49\", \"attempt_start_at\": \"2026-04-22 04:00:25\", \"waktu_akses_detik\": 1354, \"waktu_detik_saat_close\": 1354}', '2026-04-21 21:01:58', '2026-04-21 21:23:00', NULL),
('019db37c-b30c-7325-aaa2-602c03a7f0b4', 'f9a0adde-9934-4f84-aec2-dac86b3ef9b5', '244107020096', 'MUHAMMAD RIFKY PRADITYA', '019873da-b95c-7218-80ca-086512e0c5a1', 'TI-1F', '01995dec-678e-70cf-854a-b25e2c2d0d28', 'Tipe Data', '01995df6-35ed-7363-9d42-578622c3e4f2', 'Program Hitung Harga Motor', 19, '2026-04-21 21:38:54', '2026-04-21 21:51:51', NULL, 'Gaming the System', 12, 1, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-22 11:39:47 WIB\", \"respons\": \"Halo! Mari kita bedah soal ini agar kamu lebih teliti dalam memahami konsepnya.\\n\\n**Penjelasan Soal**\\nTujuan soal ini adalah menghitung total uang yang harus dibayar Pak Hari untuk sepeda motor, termasuk harga awal dan pajak penjualan.\\n\\n**Tipe Data**\\n-   **double**: Digunakan untuk menyimpan angka desimal dengan presisi tinggi. Sangat cocok untuk nilai uang yang besar seperti harga motor (25.000.000) dan hasil perhitungan pajak yang mungkin memiliki desimal.\\n-   **int**: Digunakan untuk menyimpan bilangan bulat. Dapat digunakan untuk persentase jika diinterpretasikan sebagai bilangan bulat (misalnya, 10 untuk 10%), tetapi perhitungannya nanti perlu diubah ke desimal.\\n-   **float**: Digunakan untuk menyimpan angka desimal, namun dengan presisi lebih rendah dibanding **double**. Bisa digunakan untuk harga, tetapi **double** lebih disarankan untuk perhitungan keuangan yang membutuhkan akurasi tinggi.\\n\\n**Algoritma**\\n1.  Definisikan harga awal motor.\\n2.  Hitung jumlah pajak berdasarkan persentase yang diberikan.\\n3.  Jumlahkan harga awal motor dengan jumlah pajak.\\n\\n**Petunjuk Memahami Soal**\\n1.  Pikirkan, nilai mana yang sebaiknya menggunakan tipe data **double** atau **float**, dan mana yang bisa **int**? Ingat tentang presisi.\\n2.  Bagaimana cara mengonversi persentase (10%) menjadi angka yang bisa digunakan dalam perhitungan matematika?\\n3.  Urutan operasi sangat penting. Apakah pajak dihitung dulu, baru ditambahkan, atau ada cara lain?\\n4.  Perhatikan setiap angka dalam soal. Apa peran masing-masing angka tersebut?\", \"created_at\": \"2026-04-22 04:39:47\"}], \"access_id\": \"019db37c-94f6-70fc-89e2-3505d2013ce2\", \"waktu_detik\": 776, \"durasi_detik\": 732, \"triggered_at\": \"2026-04-22 04:39:47\", \"jumlah_langkah\": 19, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-22 04:51:51\", \"popup_opened_at\": \"2026-04-22 04:39:39\", \"attempt_start_at\": \"2026-04-22 04:38:54\", \"waktu_akses_detik\": 776, \"waktu_detik_saat_close\": 776}', '2026-04-21 21:39:47', '2026-04-21 21:51:51', NULL),
('019db394-b67f-71ea-9c9a-f3861bf8b6ba', '8931bff0-40ab-4776-8177-438b85b4c72c', '244107020145', 'MUKHAMMAD SYAIFUDIN ADN', '019873da-b95c-7218-80ca-086512e0c5a1', 'TI-1F', '019863c4-59f9-7319-9104-08267fc3c551', 'Queue', '01996b09-9329-7208-be28-2b82f0987b22', 'Menambah Antrian', 23, '2026-04-21 22:05:09', '2026-04-21 23:29:35', NULL, 'Gaming the System', 83, 1, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-22 12:06:00 WIB\", \"respons\": \"**Penjelasan Soal**\\nSoal ini meminta Anda membuat pseudocode untuk menambahkan pelanggan baru ke dalam **Queue** antrian, dengan memastikan antrian tidak penuh terlebih dahulu.\\n\\n**Tipe Data**\\n*   **string[]**: Dapat digunakan untuk merepresentasikan antrian pelanggan secara internal.\\n*   **string**: Digunakan untuk nama pelanggan baru yang akan ditambahkan.\\n*   **int**: Digunakan untuk menyimpan ukuran antrian atau indeks.\\n\\n**Kondisi**\\n*   `IF`: Digunakan untuk memeriksa apakah antrian sudah penuh.\\n\\n**Fungsi**\\n*   `enqueue()`: Operasi standar untuk menambahkan elemen ke belakang antrian.\\n\\n**Queue**\\n*   **Queue** adalah struktur data yang mengikuti prinsip FIFO (First-In, First-Out), di mana elemen yang pertama masuk akan pertama keluar.\\n\\n**Algoritma**\\n1.  Menerima data pelanggan baru.\\n2.  Memeriksa kondisi apakah antrian sudah penuh.\\n3.  Jika tidak penuh, tambahkan pelanggan ke antrian.\\n\\n**Petunjuk Memahami Soal**\\n1.  Fokus pada kondisi \\\"memeriksa apakah sudah penuh\\\". Pikirkan apa yang terjadi jika **Queue** penuh dan jika tidak.\\n2.  Pahami operasi `enqueue()`: di mana posisi pelanggan baru akan ditambahkan dalam **Queue**?\\n3.  Perhatikan urutan langkah: pemeriksaan kondisi harus dilakukan *sebelum* penambahan.\", \"created_at\": \"2026-04-22 05:06:00\"}], \"access_id\": \"019db394-9ca8-713a-b121-f946b3da22f7\", \"waktu_detik\": 5065, \"durasi_detik\": 5021, \"triggered_at\": \"2026-04-22 05:06:00\", \"jumlah_langkah\": 23, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-22 06:29:35\", \"popup_opened_at\": \"2026-04-22 05:05:54\", \"attempt_start_at\": \"2026-04-22 05:05:09\", \"waktu_akses_detik\": 5065, \"waktu_detik_saat_close\": 5065}', '2026-04-21 22:06:00', '2026-04-21 23:29:36', NULL),
('019db446-bb44-722e-8639-10242cadb319', '32895896-3f06-45f0-9d74-cc1d5a06fdd1', '2341720255', 'NABHAN RIZQI JULIAN SAPUTRO', '019873da-b95c-7218-80ca-086512e0c5a1', 'TI-1F', '019863c4-59f9-7319-9104-08267fc3c551', 'Queue', '01996b09-9329-7208-be28-2b82f0987b22', 'Menambah Antrian', 19, '2026-04-22 01:19:29', '2026-04-22 01:21:05', NULL, 'Struggling', 0, 1, '[ADAPTIVE - Struggling] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Struggling] Bimbingan materi otomatis\", \"waktu\": \"2026-04-22 15:20:27 WIB\", \"respons\": \"Maaf, saya sedang tidak dapat merespons saat ini. Silakan coba lagi.\", \"created_at\": \"2026-04-22 08:20:27\"}, {\"waktu\": \"2026-04-22 15:20:55 WIB\", \"source\": \"adaptive_conversation\", \"bot_name\": \"PseudoLearn Chatbot AI\", \"access_id\": \"019db446-a806-7314-9a96-3d0c84563934\", \"created_at\": \"2026-04-22 08:20:55\", \"bot_response\": \"Halo! Selamat datang di PseudoLearn Chatbot. Senang sekali bisa membantumu di sini.\\n\\nSaya adalah asisten belajarmu di platform PseudoLearn, siap membantu kamu memahami berbagai konsep pemrograman, struktur data, dan algoritma. Saat ini, kita sedang fokus membahas tentang **Queue** (Antrean).\\n\\nAda yang bisa saya bantu atau ada pertanyaan seputar Queue hari ini? Jangan ragu untuk bertanya, ya!\", \"mahasiswa_name\": \"NABHAN RIZQI JULIAN SAPUTRO\", \"mahasiswa_message\": \"hallo\"}], \"access_id\": \"019db446-a806-7314-9a96-3d0c84563934\", \"waktu_detik\": 95, \"durasi_detik\": 41, \"triggered_at\": \"2026-04-22 08:20:27\", \"jumlah_langkah\": 19, \"total_messages\": 2, \"popup_closed_at\": \"2026-04-22 08:21:05\", \"popup_opened_at\": \"2026-04-22 08:20:24\", \"attempt_start_at\": \"2026-04-22 08:19:29\", \"waktu_akses_detik\": 95, \"waktu_detik_saat_close\": 95}', '2026-04-22 01:20:27', '2026-04-22 01:21:03', NULL),
('019db84b-c250-7279-89b2-11f1e9f0ddc3', '29f7a751-2c08-42b5-996a-76b4a19dc2b0', '244107020054', 'NABILLAH UMI PURNAMA', '019873da-b95c-7218-80ca-086512e0c5a1', 'TI-1F', '01995dec-678e-70cf-854a-b25e2c2d0d28', 'Tipe Data', '01995df6-35ed-7363-9d42-578622c3e4f2', 'Program Hitung Harga Motor', 20, '2026-04-22 20:03:45', '2026-04-22 21:16:41', NULL, 'Gaming the System', 72, 1, '[ADAPTIVE - Gaming the System] Bimbingan materi otomatis', '{\"source\": \"realtime-adaptive-trigger\", \"messages\": [{\"pesan\": \"[ADAPTIVE - Gaming the System] Bimbingan materi otomatis\", \"waktu\": \"2026-04-23 10:04:25 WIB\", \"respons\": \"**Penjelasan Soal**\\nSoal ini menghitung total harga motor setelah dikenakan pajak.\\n\\n**Tipe Data**\\n-   **int**: Untuk bilangan bulat (misal: jumlah).\\n-   **float**: Untuk bilangan desimal presisi standar (misal: persentase).\\n-   **double**: Untuk bilangan desimal presisi tinggi (ideal untuk nilai uang besar).\\n\\n**Algoritma**\\n-   Definisikan harga motor.\\n-   Hitung nilai pajak.\\n-   Jumlahkan harga dan pajak.\\n\\n**Petunjuk Memahami Soal**\\n1.  Pilih tipe data yang tepat untuk harga motor agar perhitungan akurat.\\n2.  Ubah persentase pajak menjadi angka desimal sebelum perhitungan.\\n3.  Susun langkah perhitungan berurutan: hitung pajak, lalu total.\\n4.  Perhatikan **float** vs **double** untuk presisi nilai uang.\", \"created_at\": \"2026-04-23 03:04:25\"}], \"access_id\": \"019db84b-88dc-7170-bef9-5b5e48ac4312\", \"waktu_detik\": 4376, \"durasi_detik\": 4351, \"triggered_at\": \"2026-04-23 03:04:25\", \"jumlah_langkah\": 20, \"total_messages\": 1, \"popup_closed_at\": \"2026-04-23 04:16:41\", \"popup_opened_at\": \"2026-04-23 03:04:10\", \"attempt_start_at\": \"2026-04-23 03:03:45\", \"waktu_akses_detik\": 4376, \"waktu_detik_saat_close\": 4376}', '2026-04-22 20:04:25', '2026-04-22 21:16:42', NULL);
