INSERT INTO `ujian_konversi` (`id`, `id_level`, `id_soal_konversi`, `id_mahasiswa`, `jawaban`, `output`, `nilai`, `waktu`, `created_at`, `updated_at`, `deleted_at`) VALUES
('01996b25-1abf-7072-ab00-cd6402bccbe0', '01995dec-678e-70cf-854a-b25e2c2d0d28', '0199651d-b77a-7329-8b9a-0e5b6b2f16d6', '0198517f-0d58-7074-8b6d-7bb6a5a4a30e', '[\"double pajak = 0.1;\", \"int harga_motor = 25000000;\", \"int uang_bayar;\", \"float pajak_jual;\", \"pajak_jual = pajak * harga_motor;\", \"uang_bayar = harga_motor + pajak_jual;\", \"System.out.print(uang_bayar);\"]', '27500000', 100, 42, '2025-09-21 07:20:17', '2025-09-21 07:20:17', NULL),
('01997042-3573-7382-b41c-a442c711f2f9', '01995dec-678e-70cf-854a-b25e2c2d0d28', '01996525-5cf1-7256-8f2f-184909a171ff', '0198517f-0d58-7074-8b6d-7bb6a5a4a30e', '[\"int harga_dasar;\", \"float persentase_pajak;\", \"int harga_akhir;\", \"float nilai_pajak;\", \"harga_dasar = 85000;\", \"persentase_pajak= 0.1f;\", \"nilai_pajak = harga_dasar * persentase_pajak;\", \"harga_akhir = harga_dasar + nilai_pajak;\", \"System.out.print(harga_akhir);\"]', '93500', 97, 49, '2025-09-22 07:10:11', '2025-09-22 07:10:12', NULL),
('01997045-beb1-73f7-ab32-5fb7885f99c2', '01995dec-678e-70cf-854a-b25e2c2d0d28', '0199652a-ab5d-7201-b71c-3e984cfd80f4', '0198517f-0d58-7074-8b6d-7bb6a5a4a30e', '[\"int panjang = 10;\", \"int lebar = 6;\", \"float tinggi = 1.5f;\", \"double luas_bagian;\", \"System.out.println(\\\"Panjang: \\\" + panjang + \\\", Lebar: \\\" + lebar + \\\", Tinggi: \\\" + tinggi);\", \"luas_bagian = 2 * ((panjang * lebar) + (panjang * tinggi) + (lebar * tinggi));\", \"System.out.print(luas_bagian);\"]', 'Panjang: 10, Lebar: 6, Tinggi: 1.5\n168.0', 100, 92, '2025-09-22 07:14:03', '2025-09-22 07:14:03', NULL),
('01997047-f178-7251-bb2c-7d1ba641f16c', '01995dec-678e-70cf-854a-b25e2c2d0d28', '01996533-c470-7186-8aff-58267983f830', '0198517f-0d58-7074-8b6d-7bb6a5a4a30e', '[\"int panjang = 20;\", \"int lebar = 20;\", \"int tinggi = 7;\", \"long volume;\", \"System.out.println(\\\"Panjang: \\\" + panjang + \\\", Lebar: \\\" + lebar + \\\", Tinggi: \\\" + tinggi);\", \"volume = panjang * lebar * tinggi;\", \"System.out.print(\\\"Volume setiap box nasi sebesar: \\\" + volume);\"]', 'Panjang: 20, Lebar: 20, Tinggi: 7\nVolume setiap box nasi sebesar: 2800', 100, 30, '2025-09-22 07:16:27', '2025-09-22 07:16:27', NULL),
('01997049-7c25-7172-bb9a-1afe8f78b14f', '01995dec-678e-70cf-854a-b25e2c2d0d28', '0199653d-66d4-7335-bfdc-34bd3f31837d', '0198517f-0d58-7074-8b6d-7bb6a5a4a30e', '[\"int r = 42;\", \"float phi = 3.14f;\", \"double taman_bunga;\", \"System.out.println(\\\"Jari-jari: \\\" + r + \\\", phi: \\\" + phi);\", \"taman_bunga = 0.5 * (phi * r * r);\", \"System.out.print(\\\"Luas dari taman bunga sebesar: \\\" + taman_bunga);\"]', 'Jari-jari: 42, phi: 3.14\nLuas dari taman bunga sebesar: 2769.47998046875', 100, 21, '2025-09-22 07:18:08', '2025-09-22 07:18:08', NULL),
('0199843a-fbfb-73f5-9eb3-c26ad191edb8', '01995dec-678e-70cf-854a-b25e2c2d0d28', '0199651d-b77a-7329-8b9a-0e5b6b2f16d6', '46b72ef4-35e3-4642-9b8f-e55ac06c6755', '[\"double pajak = 0.1;\", \"int harga_motor = 25000000;\", \"int uang_bayar;\", \"float pajak_jual;\", \"pajak_jual = pajak*harga_motor;\", \"uang_bayar = harga_motor + pajak_jual;\", \"System.out.print(uang_bayar);\"]', '27500000', 96, 464, '2025-09-26 04:14:42', '2025-09-26 04:14:43', NULL);
